// Versionshistorie (ab v2.7): Seite Versionen der Oberfläche und Doku\Versionshistorie.txt.
// Jede neue Version bekommt hier oben einen Eintrag (ein Test prüft, dass es einen für $ScriptVersion gibt).
// Einzelheiten stehen in Doku\Änderungen_vX.Y.txt. Für 1.0 bis 2.1 gibt es keine Änderungsdateien mehr; die Einträge
// nennen nur, was im Quelltext und in den Änderungen zu 2.2 belegt ist.
public static class Versionshistorie
{
    public class Eintrag
    {
        public string Version, Datum, Titel, Text;
        public Eintrag(string version, string datum, string titel, string text) { Version = version; Datum = datum; Titel = titel; Text = text; }
    }

    public static readonly Eintrag[] Liste = new Eintrag[] {
        new Eintrag("4.08", "12.11.2026", "Ergebnis als Seite, Benchmark und Diagnose im Stil der übrigen Seiten",
            "\u2022 Ergebnis: neuer Eintrag \u201EErgebnis\u201C in der Seitenleiste direkt unter Start, mit der Punktzahl als Pille. Er erscheint, sobald es ein Ergebnis gibt, und bleibt bis zum nächsten Lauf. Die Ergebnisseite ist jetzt eine Seite wie jede andere: Die Fußleiste bleibt, der Wechsel weg und zurück baut nichts neu auf, und Punktzahl, Balken und Ringe laufen nur beim ersten Anzeigen nach einem Lauf auf ihren Wert.\r\n" +
            "\u2022 Ergebnis nach dem Programmstart: \u201EErgebnis\u201C zeigt den letzten Lauf dieses PCs aus der Datenbank. Der Knopf \u201EErgebnis\u201C in der Karte \u201ELetzter Lauf\u201C der Startseite und der neue Kasten \u201ELetztes Ergebnis auf diesem PC\u201C der Seite Benchmark führen dorthin.\r\n" +
            "\u2022 \u201EReferenz ändern\u201C öffnet die Seite Benchmark bei der Referenz und zeigt dort das Band \u201EZurück zum Ergebnis\u201C mit Datum und Punktzahl des Laufs. Bis v4.07 führte von dort kein Weg zurück. Statt \u201EZurück\u201C gibt es \u201EErneut messen\u201C (derselbe Weg wie der Startknopf).\r\n" +
            "\u2022 Datenbank: Der Lauf speichert den Vergleich mit der Referenz (Name der Referenz, Prozent für Prozessor, Grafik, Arbeitsspeicher, Laufwerke) als optionales Feld; das Format bleibt PC-Diagnose-DB/2. Läufe vor 4.08 zeigen auf der Ergebnisseite Punktzahl, Kacheln und Befunde, beim Vergleich aber \u201Enicht gespeichert\u201C mit Verweis auf den Bericht. Nachgerechnet wird nichts.\r\n" +
            "\u2022 Seite Benchmark neu aufgebaut: links die Karte \u201EMessungen\u201C mit je einer Zeile (Symbol, Beschreibung, Dauer, Schalter) und \u201EAlle an \u00B7 Alle aus\u201C. Die Einstellungen stehen unter ihrer Messung und nur, wenn sie eingeschaltet ist: unter Grafik der Rendertest, unter Laufwerke die Datenträger als kompakte Zeilen mit Anbindung und freiem Platz. Rechts die Referenz und das letzte Ergebnis. Das Listenfeld mit hellem Rahmen entfällt, die Seite nutzt die ganze Breite.\r\n" +
            "\u2022 Seite Diagnose neu aufgebaut: Umfang als Auswahl mit drei Feldern (Schnell, Vollständig, Eigene Auswahl, je mit Anzahl und Dauer), die Prüfungen immer sichtbar als Zeilen mit Schalter, Kurztitel und Dauer; \u201Eläuft nebenher\u201C kennzeichnet, was bei paralleler Ausführung nebenher läuft. Rechts Ausführung, Zusätze und Zeiträume. Ein umgelegter Schalter wechselt wie bisher zur eigenen Auswahl.\r\n" +
            "\u2022 Beide Seiten ordnen sich unter 900 px Seitenbreite in einer Spalte. Vorlagen, Zeitschätzung und Startparameter sind unverändert; gespeicherte Vorlagen laden wie bisher.\r\n" +
            "\u2022 Startfenster: zeigt die Version des Skripts, das tatsächlich läuft. Liegt neben LMB.exe ein Skript einer anderen Version, steht das im Startfenster und in Start.log (bei 4.07 lief so unbemerkt noch 4.06).\r\n" +
            "\u2022 Behoben: Die Kopfkarte der Ergebnisseite blieb unter Windows unten rund 130 px leer, die Seite brauchte dadurch eine Bildlaufleiste und der Titel war abgeschnitten. \u201EAlle Befunde im Bericht\u201C stand über dem Text statt darunter. Während das Ergebnis zu sehen war, blieb das zuletzt gewählte Modul markiert. \u201E100 % =\u201C nannte bei der gespeicherten Referenz nur \u201EGespeicherte Referenz\u201C statt ihres Namens."),
        new Eintrag("4.07", "10.11.2026", "Eine Datei je Seite, kürzerer Start, Akzentfarbe und dezente Bewegung",
            "\u2022 Akzentfarbe: In den Einstellungen wählbar (Blau, Türkis, Violett, Pink, Orange oder die Akzentfarbe aus Windows). Sie gilt sofort für Schalter, Knöpfe, Markierungen und Verweise, in beiden Farbschemata mit geprüftem Kontrast. Etiketten mit Bedeutung (Ändern, Warnung, Kritisch) behalten ihre Farbe.\r\n" +
            "\u2022 Ergebnisseite: Die Punktzahl zählt hoch, die Balken im Vergleich füllen sich, jede Komponente trägt einen Ring mit ihrem Anteil an der Referenz (voller Ring = 100 %). Alles dauert 0,7 s und zeigt nur gemessene Werte.\r\n" +
            "\u2022 Seitenwechsel mit kurzer Überblendung (0,14 s). Braucht ein PC für das Bild der Seite länger als 45 ms, bleibt sie für diesen Programmlauf aus. Einstellungen › Animationen schaltet jede Bewegung ab; sie bleibt auch aus, wenn Windows Animationen abgeschaltet hat oder eine Remotesitzung läuft.\r\n" +
            "\u2022 Startzeit: Die Oberfläche wird nicht bei jedem Start übersetzt, sondern liegt bereits als DLL im Cache (Stick: 0,65 s Laden statt 2,5 s Übersetzen, nur der erste Start einer Version übersetzt). Neu: Die Hardwareabfrage fragt nur die gebrauchten Eigenschaften ab (Win32_Processor ermittelte sonst nebenbei die Auslastung, was den Start aufhielt), die Datenpflege läuft nur noch, wenn sich Datenbank oder Berichte geändert haben (bisher 0,8 bis 1,5 s je Start), Datenbank und Änderungsprotokoll werden gleichzeitig gelesen.\r\n" +
            "\u2022 Start.log nennt jetzt die Dauer der Hardwareabfrage und die Aufbauzeit jeder Seite.\r\n" +
            "\u2022 Ergebnisseite: Ein Datenbankeintrag ohne Berichtsordner (importiert oder Referenz) passte bisher auf jeden Lauf; stand er alphabetisch vorn, zeigte die Ergebnisseite Punktzahl und Hardware eines anderen PCs.\r\n" +
            "\u2022 Quelltext: Jede Seite der Oberfläche hat eine eigene Datei (DiagGui_<Seite>.cs statt zwei Dateien mit 5.371 und 3.988 Zeilen), ohne Änderung am Verhalten. Doku\\Projektstand.md von 332 auf 91 Zeilen gekürzt."),
        new Eintrag("4.06", "09.11.2026", "Update-Pr\u00FCfung und Referenz repariert",
            "\u2022 Update-Pr\u00FCfung: \u201EJetzt suchen\u201C fragt immer neu bei GitHub und meldet das Ergebnis. Bis v4.05 galt das Ergebnis einer Pr\u00FCfung 24 Stunden, auch f\u00FCr \u201EJetzt suchen\u201C; eine Pr\u00FCfung kurz vor einem Release meldete so einen Tag lang kein Update. Beim Start gilt das letzte Ergebnis jetzt h\u00F6chstens zwei Stunden.\r\n" +
            "\u2022 Update-Pr\u00FCfung: Antwortet die GitHub-API nicht (Grenze von 60 Abfragen je Stunde und Netz, Frist), liest Leos Minibench die neueste Version \u00FCber github.com und die Pr\u00FCfsumme aus dem neuen Anhang LMB.exe.sha256. Frist 10 statt 3 Sekunden, Systemproxy mit Anmeldung des Benutzers.\r\n" +
            "\u2022 Median aktualisieren: Die Meldung lautete immer \u201EAktualisierung fehlgeschlagen\u201C, auch wenn die Dateien geschrieben waren. Jetzt nennt sie je Datei Ger\u00E4teklasse, Anzahl der Systeme, Messgr\u00F6\u00DFen und die einbezogenen PCs.\r\n" +
            "\u2022 Referenz: Der Median aller Systeme \u00FCberschrieb bisher Referenz.json, die in der Datenbank festgelegte eigene Referenz, und der Median der Ger\u00E4teklasse hatte Vorrang vor ihr. Jetzt steht der Median in Referenz_Median.json, die eigene Referenz geht vor, ein alter Median in Referenz.json kommt ins Archiv.\r\n" +
            "\u2022 Referenz: Die Seite Benchmark zeigt, welche Referenz gilt und von wann; Median-Dateien enthalten nur gemessene Lasttestwerte (vorher feste Ersatzwerte ohne Messung).\r\n" +
            "\u2022 Veroeffentlichen.ps1 h\u00E4ngt LMB.exe.sha256 an das Release an."),
        new Eintrag("4.05", "09.11.2026", "Bereits aktive Optimierungen gesperrt, Tools-Seite kompakt, 28 Softwarepakete",
            "\u2022 Optimierung: Eintr\u00E4ge, die auf diesem PC schon so eingestellt sind (Zustand \u201Ebereits aktiv\u201C), stehen nach der Hintergrundpr\u00FCfung auf An und sind gesperrt, gut lesbar in Gr\u00FCn statt ausgegraut. Vorlagen, \u201EAlle an\u201C, \u201EAlle aus\u201C und geladene eigene Vorlagen \u00E4ndern sie nicht; der Hinweis nennt den Weg zur\u00FCck \u00FCber die Seite \u00C4nderungen.\r\n" +
            "\u2022 Optimierung: Die Seitenleiste z\u00E4hlt gew\u00E4hlte und bereits aktive Eintr\u00E4ge getrennt (blaue Pille \u201E3/17\u201C, gr\u00FCne Pille \u201E5 \u2713\u201C), der Kopf der Kategorie nennt \u201E3 gew\u00E4hlt \u00B7 5 bereits aktiv \u00B7 17 Eintr\u00E4ge\u201C.\r\n" +
            "\u2022 Optimierung im Lauf: Vor dem Wiederherstellungspunkt wird der Zustand jedes gew\u00E4hlten Eintrags gepr\u00FCft; bereits aktive laufen nicht, sondern stehen als \u201Ebereits aktiv\u201C im Bericht. Bleibt nichts zu \u00E4ndern, entsteht kein Wiederherstellungspunkt. Angewendete Eintr\u00E4ge sind danach ebenfalls gesperrt.\r\n" +
            "\u2022 Tools: kompakte Zeilen (50 statt 68 px), bei breitem Fenster in zwei Spalten; je Werkzeug Zustand, eine Zeile Beschreibung, \u201EStarten\u201C oder \u201EHerunterladen\u201C und ein Men\u00FC \u201E\u2026\u201C mit Speicherort und Herstellerseite. \u201ENeu scannen\u201C und \u201ETools-Ordner\u201C stehen rechts im Seitenkopf. Der Abschnitt Netzlaufwerk entf\u00E4llt (Einstellungen \u203A Daten und Datenschutz).\r\n" +
            "\u2022 Neue Werkzeuge CPU-Z, GPU-Z und MSI Afterburner: erkannt im Tools-Ordner oder als Installation, sonst Verweis auf die Herstellerseite. GPU-Z wird mit Versionsnummer im Namen gefunden (GPU-Z*.exe, neueste Version).\r\n" +
            "\u2022 Softwarepakete: 28 Programme in sechs Gruppen (Browser, Kommunikation, Spiele, Office und PDF, Medien, System und Laufzeiten) als kompakte Liste; die Liste steht als Tabelle in Kern\\Softwarepakete.psd1, die winget-Kennung nur im Hinweis. Bereits installierte Programme erkennt ein Hintergrundprozess \u00FCber winget export, sie sind gr\u00FCn und gesperrt. \u201EAlle an\u201C entf\u00E4llt."),
        new Eintrag("4.04", "08.11.2026", "Veröffentlichen in einem Schritt, Referenz über die Datenbank",
            "\u2022 Seite Benchmark: Der Haken \u201EDieses System als Referenz (100 %) festlegen\u201C entf\u00E4llt. Eine Referenz legt man in der Datenbank fest (Lauf markieren, Aktionen \u203A Als Referenz festlegen), wo der Lauf mit seinen Werten sichtbar ist. Ein Hinweis unter der Auswahl der Referenz nennt den Weg.\r\n" +
            "\u2022 Veroeffentlichen.ps1 erledigt alles in einem Aufruf: pr\u00FCft, dass alles committet ist und Aktueller Build zur Version passt, \u00FCbertr\u00E4gt main und den Tag, installiert und meldet die GitHub CLI bei Bedarf an und erstellt das Release mit LMB.exe und Pr\u00FCfsumme.\r\n" +
            "\u2022 .gitignore: Ordner \u201EClaude outputs\u201C wird nicht mehr als neue Datei gemeldet."),
        new Eintrag("4.03", "08.11.2026", "Update-Funktion, SMART-Langtest, Datenbank und Feinschliff",
            "\u2022 Update: Der Austausch der Programmdatei griff seit seiner Einf\u00FChrung auf powershell.exe statt auf LMB.exe zu und \u00F6ffnete nur ein PowerShell-Fenster. Jetzt wird LMB.exe ersetzt, sobald sie frei ist, das Skript daneben mit archiviert, das Ergebnis in Minibench-Daten\\Update\\Update.log festgehalten und bei Fehlern die alte Version zur\u00FCckgelegt. Versionen werden dezimal verglichen (4.03 < 4.1).\r\n" +
            "\u2022 SMART-Langtest: Wird das Warten \u00FCbersprungen oder steht die Datentr\u00E4germessung an, beendet Leos Minibench den Langtest (smartctl -X), damit er Benchmark und Lasttest nicht bremst.\r\n" +
            "\u2022 Grafik: Die PCIe-Anbindung wird w\u00E4hrend des Rendertests gelesen, nicht im Leerlauf danach (GTX 1070 stand vorher mit PCIe 1.0 im Bericht).\r\n" +
            "\u2022 Datenbank: Kn\u00F6pfe f\u00FCr einen Lauf erscheinen erst, wenn einer markiert ist. Das Men\u00FC Aktionen enth\u00E4lt Berichtsordner \u00F6ffnen und Lauf l\u00F6schen; der Knopf Lauf l\u00F6schen entf\u00E4llt.\r\n" +
            "\u2022 Ergebnisseite: Verweis \u201EReferenz \u00E4ndern\u201C f\u00FChrt zur Wahl der Referenz, die auf der Seite Benchmark jetzt direkt unter den Messungen steht.\r\n" +
            "\u2022 Lauf: W\u00E4hrend Sensoren beendet und vor\u00FCbergehende Treiber entfernt werden, steht \u201EAufr\u00E4umen\u201C in der Kopfzeile statt des letzten Abschnitts.\r\n" +
            "\u2022 Sensorkurven: Legende und Abbruchschwelle laufen nicht mehr ineinander; Abst\u00E4nde skalieren mit der Anzeigeskalierung.\r\n" +
            "\u2022 Veroeffentlichen.ps1 erstellt das GitHub-Release mit LMB.exe und der SHA-256-Zeile, die die Update-Funktion pr\u00FCft."),
        new Eintrag("4.02", "08.11.2026", "PawnIO-Entfernung, plausiblere Messwerte, Einstellungen auf einer Seite",
            "\u2022 PawnIO: Der Treiber wurde seit v3.84 am Ende des Laufs nicht entfernt. Das Setup kennt nur -uninstall -silent, die zus\u00E4tzlichen InnoSetup- und NSIS-Schalter f\u00FChrten zum Fenster \u201EUnknown argument: /VERYSILENT\u201C und R\u00FCckgabecode 87. Ein noch installierter Treiber aus fr\u00FCheren L\u00E4ufen wird beim n\u00E4chsten Lauf entfernt.\r\n" +
            "\u2022 Laufwerke mit Medientyp \u201EUnspecified\u201C (SATA hinter AMD- oder Intel-Treibern) werden \u00FCber Name und 4K-Zugriffszeit als SSD oder Festplatte eingeordnet und bekommen wieder Index und Referenzvergleich.\r\n" +
            "\u2022 L\u00E4uft der SMART-Langtest w\u00E4hrend der Datentr\u00E4germessung noch, steht das als Hinweis im Bericht; die Werte dieser Laufwerke k\u00F6nnen zu niedrig sein.\r\n" +
            "\u2022 Hintergrundlast vor Messungen nennt die Prozesse mit der CPU-Last der letzten zwei Sekunden statt der seit dem Prozessstart gesammelten CPU-Zeit und ohne die eigene PowerShell.\r\n" +
            "\u2022 Netzwerk: Ohne DNS-Server eine Warnung statt vier (drei Namen und HTTPS). Autostart-Verz\u00F6gerer je Programm einmal mit dem l\u00E4ngsten Wert, ohne leere Klammern.\r\n" +
            "\u2022 Ergebnisseite: Einordnung gegen\u00FCber dem Referenz-PC (schneller, gleichauf, etwas langsamer, langsamer, deutlich langsamer) statt \u201EUnterdurchschnittlich\u201C; Name des Referenz-PCs \u00FCber den Balken; nicht gemessene Gruppen als \u201Enicht gemessen\u201C; eine Pille je Laufwerk statt einer abgeschnittenen Zeile.\r\n" +
            "\u2022 Einstellungen auf einer Seite: Allgemein, Daten und Datenschutz, \u00DCber; je Option eine Zeile mit Schalter statt eines Reiters je Option.\r\n" +
            "\u2022 Optimierung: Der Zustand der Eintr\u00E4ge wird nach dem Start im Hintergrund mit niedriger Priorit\u00E4t gelesen. Der Knopf \u201EZustand pr\u00FCfen\u201C entf\u00E4llt, das Fenster friert dabei nicht mehr ein.\r\n" +
            "\u2022 Protokoll des Laufs ohne doppelte Abschnittszeilen; Texte \u201E1 Bedrohungserkennung\u201C und \u201E1 Funktionsupdate\u201C in der Einzahl."),
        new Eintrag("4.01", "07.11.2026", "Politur der Oberfläche: Ergebnisseite, Einstellungen, Startzeit und Skalierung",
            "\u2022 Umlaute: Die Doppelkodierungen aus 4.0 (\u201Ef\u00C3\u00BCr\u201C, \u201ESchlie\u00C3\u0178en\u201C, \u201E\u00C3\u0153ber\u201C) in Einstellungen, Optimierung und Datenbank sind behoben, ebenso in CHANGELOG, Versionshistorie und Projektstand.\r\n" +
            "\u2022 Modulwahl nur noch \u00FCber den Haken in der Seitenleiste: Der Schalter \u201Ebeim Start ausf\u00FChren\u201C im Seitenkopf entf\u00E4llt. Ist ein Modul nicht angehakt, zeigt seine Seite ein Hinweisband mit \u201EIn den Ablauf aufnehmen\u201C.\r\n" +
            "\u2022 Fu\u00DFleiste: Ablauf-Vorlagen hei\u00DFen Schnellcheck, Standard, Komplett und Alles abw\u00E4hlen; Minimal, Leos Empfehlung und Erweitert gibt es nur noch auf der Seite Optimierung. Ablage, Anonymisierung und 1-Fenstermodus stehen nicht mehr in der Fu\u00DFleiste. Auf Werkzeugseiten bleibt nur Ablaufzeile und Startknopf.\r\n" +
            "\u2022 Ergebnisse erscheinen immer im Programmfenster; die Option 1-Fenstermodus entf\u00E4llt.\r\n" +
            "\u2022 Datenbank: Suchfeld und die nie angezeigte Leerkarte entfernt, Einleitung gek\u00FCrzt, Knopf Aufr\u00E4umen statt Men\u00FC Mehr (Datenordner und Netzlaufwerk stehen in den Einstellungen), Spalte Grafiktest statt FPS, RAM-Spalte breiter.\r\n" +
            "\u2022 Optimierung und Wartung: Kategorielisten nutzen die Kurztitel und Symbole aus Katalog und Vertrag; \u201E&\u201C wird nicht mehr als Unterstrich gezeichnet. Das Etikett \u00C4ndern steht nicht mehr in jeder Zeile der Optimierung, die Legende erkl\u00E4rt es.\r\n" +
            "\u2022 Einstellungen: eigenes Fenster im Aufbau der Seiten, links die Bereiche Darstellung, Start, Datenschutz, Daten, Updates und \u00DCber, rechts eine Karte mit den Optionen; dunkle Titelleiste aller Dialoge im Dunkelschema. Startseiten-Option nur noch hier, Datenbereinigung nur noch in der Datenbank.\r\n" +
            "\u2022 Ergebnisseite: oben Urteil aus den Befunden mit Gesamtpunktzahl, darunter die f\u00FCnf wichtigsten Befunde und die Leistung je Gruppe als Balken gegen\u00FCber der Referenz mit Einordnung (Hervorragend bis Unterdurchschnittlich). Kacheln mit einem Hauptwert und Einordnung statt drei Zahlen. Die festen Texte des alten Dashboards (DPC, Timer, ReBAR, Netzwerk) sind entfernt.\r\n" +
            "\u2022 Skalierung 125 und 150 %: Schrift in Pillen, Kategorielisten, Einstellungszeilen und Dialogk\u00F6pfen wurde doppelt skaliert und schnitt Texte ab; Schriftgr\u00F6\u00DFen sind jetzt reine Punktgr\u00F6\u00DFen.\r\n" +
            "\u2022 Farbschema zur Laufzeit: Einstellungszeilen und Kategorien bekommen beim Umschalten den neuen Hintergrund (vorher helle Ecken im Dunkelschema).\r\n" +
            "\u2022 Einheitlich \u201EAlle an / Alle aus\u201C in Tools, System-Umzug und Kategorien; Hinweise auf der Seite Sensoren umbrechen innerhalb der Gruppenbreite.\r\n" +
            "\u2022 Startzeit: Einstellungszeilen messen ihren Text ohne vorzeitiges Fensterhandle und teilen sich ihre Schriften (Aufbau der Seite Optimierung in der Sandbox etwa sechsmal schneller); Start.log nennt zus\u00E4tzlich die Phasen Hardwareabfrage abgeschlossen, Katalog der Optimierung gelesen, Datenbank geladen und Seiten aufgebaut. Laufwerke werden \u00FCber MSFT_PhysicalDisk statt Win32_DiskDrive mit Zuordnungen abgefragt, Datenpflege und Katalog laufen parallel zur Hardwareabfrage, die Zeilen der Optimierung entstehen erst beim \u00D6ffnen einer Kategorie."),
        new Eintrag("4.0", "05.11.2026", "Aufgeräumt: Ganzheitliche Vereinheitlichung und Bereinigung der Oberfläche",
            "\u2022 Ganzheitliche Vereinheitlichung der Oberfl\u00E4che: Bereinigung aller Inkonsistenzen, einheitliche Begrifflichkeiten (Lauf, System, Modul, Aufgabe, Einstellung, Vorlage, Ablauf) und Beseitigung s\u00E4mtlicher Entwicklersprache.\r\n" +
            "\u2022 Globales Einstellungs-Men\u00FC: Zentraler Zahnrad-Knopf in der Kopfzeile b\u00FCndelt alle globalen Einstellungen (Darstellung, Startseite, 1-Fenstermodus, Datenschutz/Anonymisierung, Speicherorte & Netzlaufwerk, Updates, Danksagung/Lizenzen); die Fu\u00DFleiste wurde aufger\u00E4umt und fokussiert.\r\n" +
            "\u2022 Einheitliche Einstellungszeilen (SettingRow): Dynamische H\u00F6henberechnung verhindert Textabschneiden, deterministisches Spaltenraster [Zustand] \u2192 [Risiko] \u2192 [Neustart] \u2192 [Schalter] schlie\u00DFt \u00DCberlappungen aus.\r\n" +
            "\u2022 Kategorielisten mit Kurztiteln & Symbolen: Optimierung und Wartung nutzen sprechende Kategorie-Symbole und Kurztitel gegen Text\u00FCberl\u00E4ufe; Pillen-Z\u00E4hler einheitlich in Akzentfarbe (X/Y).\r\n" +
            "\u2022 Entflechtete Datenbank-Bedienung: Strikte Trennung zwischen Haken f\u00FCr den Mehrfachvergleich im Dashboard ('Im Dashboard vergleichen') und Zeilen-Markierung f\u00FCr Einzelaktionen; neue Suchleiste, leere Zustandskarte und dynamische Spaltenbreiten.\r\n" +
            "\u2022 Dezimale Versionspr\u00FCfung & Barrierefreiheit: Korrekter dezimaler Versionsvergleich (3.882 < 3.9 < 3.91 < 4.0), vollst\u00E4ndige Tastatur-Bedienung (F5, Strg+F, Strg+Enter) und Screenreader-Attribute (AccessibleRole/AccessibleName) f\u00FCr alle interaktiven Steuerelemente."),
        new Eintrag("3.91", "31.10.2026", "Ergebnis-Dashboard, schlankes Optimierungs-Layout & Zeichensatz-Korrektur",
            "\u2022 Infoboxen auf der Ergebnisseite vergr\u00F6\u00DFert: Gro\u00DFz\u00FCgige Kachel-Mindesth\u00F6he (UI.S(132)), AutoSize-Spalte f\u00FCr Metrikbezeichnungen und rechtsb\u00FCndige Werteverankerung verhindern jedes Abschneiden oder \u00DCberlaufen von Texten (z. B. Befundz\u00E4hler, DPC-Latenzen).\r\n" +
            "\u2022 Klassifizierung entfernt: Die subjektive Klassifizierungszeile ('High-End', etc.) wurde vollst\u00E4ndig vom Ergebnis-Dashboard entfernt; die Gesamtpunktzahl steht dominant und klar gegliedert \u00FCber den Hardware-Spezifikationen.\r\n" +
            "\u2022 Schlankes Layout f\u00FCr Optimierung & Wartung: Technische Registry-Pfade und Hintergrunddetails wurden vollst\u00E4ndig in Hover-Tooltips ausgelagert; jede Einstellungszeile ist kompakt (42\u201352 px) mit pr\u00E4gnanter deutscher Kurzbeschreibung, Risikostufen-Badge und interaktivem Schalter gestaltet.\r\n" +
            "\u2022 Direkter Einstieg ohne Scrollen: Die Master-Detail-Auswahl mit Kategoriew\u00E4hler und Detailkarte wurde auf beiden Seiten ganz nach oben verlegt; Vorlagen-Pills, Aktionskn\u00F6pfe, Absicherung (Wiederherstellungspunkt) und Legende schlie\u00DFen \u00FCbersichtlich am Seitenende an.\r\n" +
            "\u2022 Vollst\u00E4ndige Zeichensatz-Bereinigung: Beseitigung aller UTF-8-Doppelkodierungen (Mojibake) in der Fu\u00DFleiste ('Speichern \u2026'), auf den Einstellungsseiten ('Zustand pr\u00FCfen', 'Werkzeuge holen \u2026', 'gew\u00E4hlt') und in den Dashboard-Diagrammen."),
        new Eintrag("3.9", "31.10.2026", "Modernisierung, 1-Fenstermodus, persistente Menüleiste & ReBAR-Korrektur (Experimentell)",
            "• Master-Detail-Layout für Optimierung & Wartung: Übersichtliches zweispaltiges Design mit Kategoriewähler links (inkl. dynamischem Zähler wie '4/9') und Detailkarte rechts mit Schnellwahl ('Alle an' / 'Alle aus').\r\n" +
            "• Interaktive Schalter (ToggleSwitch): Moderner Pillen-Schalter mit Anti-Aliasing und klarer Farbcodierung (Akzentfarbe / Grau) ersetzt altbackene Checkboxen.\r\n" +
            "• 1-Fenstermodus & Ergebnis-Dashboard: Nach Abschluss wahlweise kein Browser-Popup; Umschaltung auf ein natives Ergebnis-Dashboard mit großer Gesamtwertung, Hardware-Pills und 2x3 Kacheln für CPU, GPU, RAM, Disk, DPC/Latenz und Systeminfo.\r\n" +
            "• Persistente Menüleiste: Die linke Navigationsleiste bleibt während des gesamten Durchlaufs sichtbar; aktiver Modulschritt wird visuell mit cyanfarbenem Aktivitätsindikator hervorgehoben.\r\n" +
            "• Moderne Schnellwahl-Pills: cmbPreset durch Pill-Buttons ([Minimal] [Leos Empfehlung] [Erweitert] [Auswahl aufheben]) und dynamische Vorlagen-Pills mit [x]-Entfernen ersetzt.\r\n" +
            "• Kein Browser bei Wartung/Optimierung: Reine Pflege- und Tuningdurchläufe schließen ohne Öffnen eines externen Webbrowsers ab; Ergebnisse stehen direkt im Programmfenster.\r\n" +
            "• Hardware-Erkennung Resizable BAR / SAM: Robuste PnP-Hardwareressourcen-Erkennung (pnputil) filtert virtuelle Treiber aus und erfasst 64-Bit-Adressbereiche über 256 MB verlässlich (behebt Fehlwarnung auf AMD Radeon RX 6800)."),
        new Eintrag("3.882", "29.10.2026", "Zusammengefasste Systemnamen & Startseiten-Verlaufsknopf",
            "• Bearbeitung zusammengefasster Systemnamen: Das Umbenennen von Rechnern mit mehreren Läufen über 'Name ändern ...' (oder F2) aktualisiert alle Läufe des Systems in einem Schritt; benutzerdefinierte Gerätenamen werden in Spalte 1 (System) sowohl im eingeklappten Zustand als auch im Gruppenkopf zuverlässig anstelle des Computernamens angezeigt.\r\n" +
            "• Startseiten-Aktionsleiste: Das Layout der Kachel 'Letzter Lauf' wurde flexibilisiert (55 % Spaltenbreite im 2x2-Grid, AutoSize für den Tastenbereich und DockStyle.Fill für die Befundanzeige); die Schaltfläche 'Verlauf' wird auf allen DPI-Skalierungen vollständig und unbeschnitten dargestellt.\r\n" +
            "• Schnelltaste F2: Die Tabellenansicht der Datenbank unterstützt F2 zur sofortigen Bearbeitung des Anzeigenamens des ausgewählten Systems oder Einzellaufs."),
        new Eintrag("3.881", "29.10.2026", "Startseiten-Kachelrahmen & vollständige Datenbank-Systemdaten",
            "• Startseiten-Kachelrahmen & Layout: Saubere, unbeschnittene Umrandung aller vier Kacheln ('Letzter Lauf', 'Aufgaben', 'Schnell behebbar', 'Werkzeuge') durch PenAlignment.Inset mit 1-px-Anti-Aliasing-Sicherheitsabstand; harmonisierte Margins im 2x2-Grid (oben/unten UI.S(12)) und vergrößerter unterer Innenabstand verhindern Anstoßen an die Fußleiste.\r\n" +
            "• Vollständige Systemdaten im eingeklappten Zustand: Abkehr von nativen Win32-Gruppenköpfen (LVGS_COLLAPSED), die Datenzeilen versteckten; kompakte Master-Zeilen zeigen alle Hardware- und Benchmarkdaten des neuesten Laufs in den Spalten 2–10 (Datum, Gesamt, CPU, GPU, RAM, Mehrkern, RAM Lesen, GPU, Befunde).\r\n" +
            "• Überlaufschutz in Spalte 1: Schlanke Formatierung '▶ Name (Anzahl)' bzw. '  Name' (12–18 Zeichen) passt perfekt ohne Textabschneiden in die 135 px breite erste Spalte; das Messdatum steht ausschließlich in Spalte 2.\r\n" +
            "• Sofortige Interaktion & Aktionsknöpfe: Einzelsysteme und kompakte Gruppenköpfe sind echte Tabellenzeilen mit Tag = neuester Lauf; ein Klick aktiviert sofort alle Fußleisten-Aktionen ('Bericht öffnen', 'Verlauf', 'Im Dashboard vergleichen', 'Als Referenz'); Doppelklick öffnet den Bericht.\r\n" +
            "• Intuitive Aufklapp-Mechanik: Klick auf den Pfeil oder Doppelklick klappt das System auf ('▼ Name (Anzahl)') und listet alle Einzelläufe eingerückt darunter auf; Toolbar-Schaltfläche und Kontextmenü ('Alle aufklappen' / 'Alle einklappen') sowie Pfeiltasten (Rechts/Links) schalten synchron um.\r\n" +
            "• Hoher Dark-Mode-Kontrast: Text in Spalte 1 und allen Datenfeldern behält mindestens 7:1-Kontrast im Hell- und Dunkelmodus; Pfeilsymbole in beiden Farbschemata klar sichtbar."),
        new Eintrag("3.88", "29.10.2026", "Einklappbare Datenbank-Gruppen, Dark-Mode-Kontrast, Startseiten-Layout & Zeichensatz-Korrektur",
            "\u2022 Einklappbare Ger\u00E4tegruppen in der Datenbank: Native Win32-Unterst\u00FCtzung (LVGS_COLLAPSIBLE) mit Windows-Chevrons; Systeme mit mehreren L\u00E4ufen und Referenzsysteme starten standardm\u00E4\u00DFig kompakt eingeklappt; neue Aktionen 'Alle aufklappen / Alle einklappen' in Toolbar und Kontextmen\u00FC.\r\n" +
            "\u2022 Dark-Mode-Kontrast f\u00FCr Gruppen: Gruppenk\u00F6pfe der Datenbank-ListView werden im Dark Mode mit hohem Kontrast (>= 7:1) in UI.Accent/UI.Text gerendert (beseitigt unlesbares Windows-Theme-Dunkelblau auf schwarzem Grund).\r\n" +
            "\u2022 Startseiten-Layout: Kachel 'Letzter Lauf' gegen Textumbruch abgesichert; Befundstatus (lblBef) bricht niemals vertikal oder zeichenweise um; Aktions-Schaltfl\u00E4che pr\u00E4gnant als 'Dashboard' benannt und Buttons kompakt ausgerichtet.\r\n" +
            "\u2022 Robuste Hardware-Erkennung: Kopf-Steckbrief und System\u00FCbersicht filtern virtuelle Display-Adapter (Virtual Desktop, Parsec, spacedesk, IddSampleDriver, Remote Desktop) aus und zeigen bevorzugt die reale dedizierte Grafikkarte (dGPU, z. B. Radeon RX 6800) bzw. den physischen Grafikbeschleuniger.\r\n" +
            "\u2022 Stabilit\u00E4t des Mehrkern-Benchmarks: Mehrkern-Skalierungsbefund stuft Leistungsabf\u00E4lle bei erkannter Hintergrundlast (> 15 % CPU oder Hintergrunddienste) sachlich als INFO statt als irref\u00FChrende Warnung ein.\r\n" +
            "\u2022 Vollst\u00E4ndige Zeichensatz-Bereinigung: Beseitigung aller UTF-8-Doppelkodierungen (Mojibake) in HTML-Diagnoseberichten, Dashboard-Diagrammen und Vergleichsbausteinen; Unicode-Escape-Sequenzen f\u00FCr Pfeilsymbole der Startseiten-KPIs."),
        new Eintrag("3.87", "29.10.2026", "Läufe je Gerät bündeln (Verlauf ohne eigene Seite)",
            "• ListViewGroup-Gruppierung in der Datenbank: Die Datenbank-ListView gruppiert alle Messungen automatisch nach Geräten (Hardware-Signatur über Geraet.Id oder Computername) mit Angabe von Gerätename, Laufanzahl und jüngstem Messdatum. Referenzprofile sind am Listenende in einer geschlossenen Gruppe gebündelt. Volle Farbschema-Unterstützung (Hell/Dunkel) ohne Kontrastfehler.\r\n" +
            "• Verlauf-Aktionen in Datenbank & Startseite: Neue Schaltfläche 'Verlauf' sowie Kontextmenüeintrag 'Geräte-Verlauf im Dashboard öffnen' in der Datenbankansicht; Kachel 'Letzter Lauf' auf der Startseite mit 'Verlauf'-Button und kompakten Trend-Pfeilen (↑ +X %, ↓ -X %) für die 4 Kern-KPIs (Gesamt, CPU Mehrkern, RAM Lesen, Grafik) gegen den direkten Vorläufer desselben PCs.\r\n" +
            "• Interaktiver Verlaufsmodus im Dashboard: Timeline-Vergleich aller chronologischen Läufe des ausgewählten Rechners (von links = ältester nach rechts = neuester Lauf) mit Delta-Badges zum vorherigen Lauf, Hardware-Inventar-Differenzanalyse (BIOS, Treiber, Windows-Build, RAM-Takt) und Liniendiagrammen über die Zeit für Leistung, SSD-/Akku-Verschleiß und Höchsttemperaturen mit striktem Vergleichbarkeitsfilter.\r\n" +
            "• Neuer Berichtsabschnitt 'Seit dem letzten Lauf': Kompakte Gegenüberstellung der Kernmesswerte und Inventar-Modifikationen direkt vor der Leistungsmessung im HTML-Diagnosebericht sowie strukturierter Export in die KI-Zusammenfassung.\r\n" +
            "• Strikte 3-Läufe-Regel für Trend-Befunde: Statistische Trendwarnungen (z. B. CPU unter gleicher Last signifikant wärmer) werden frühestens ab mindestens drei Läufen und nur bei Überschreitung der doppelten Standardabweichung ausgelöst; Einzellauf-Faktenhinweis schützt vor verfrühten Warnungen.\r\n" +
            "• Lineare SSD-Verschleiß-Hochrechnung: Transparente Restlebensdauer-Prognose auf Basis von TBW / Percentage Used und Zeitintervall als geschätzte Hochrechnung des bisherigen Schreibaufkommens."),
        new Eintrag("3.86", "29.10.2026", "Update-Prüfung, Grafiktreiber-Links, Resizable BAR, geprüfter System-Umzug mit WLAN & Gesamtläufe",
            "• Asynchrone Update-Prüfung & Self-Replace: Lautlose Versionsprüfung im Hintergrund mit 24h-Cache; dezenter Badge in der Kopfzeile und Update-Kachel auf der Startseite; Download von LMB.exe nach Minibench-Daten\\Update\\, SHA-256-Validierung und nahtloser Austausch mit Archivierung nach Minibench-Daten\\Archiv\\v<alteVersion>\\ über Update.cmd; abschaltbar über Einstellungen.\r\n" +
            "• Offizielle Grafiktreiber-Links & Laptop-Hinweis: Direkte Hersteller-Downloadlinks für NVIDIA, AMD und Intel; dedizierte Schnell-behebbar-Karte mit 'Treiber laden'-Schaltfläche bei Treibern älter als 18 Monate; klarer OEM-Hinweis bei Hybridgrafik auf Notebooks; zusätzliche Treiberversions-Gegenprüfung via nvidia-smi.\r\n" +
            "• Resizable BAR / Smart Access Memory Erkennung: Hardwareseitige Erkennung für NVIDIA (BAR1-Speichergröße), AMD und Intel (64-Bit PCI-Speicherfenster über 256 MB); Verifizierung der Plattformunterstützung (RTX 3000+, RX 6000+, Arc / Ryzen 3000+, Intel 10th Gen+); gelbe Diagnosewarnung und interaktiver BIOS-Leitfaden nur bei inaktivem ReBAR auf unterstützter Hardware.\r\n" +
            "• System-Umzug mit WLAN-Profilen: Lautloser Export von WLAN-Profilen per netsh wlan; Klartext-Export von Kennwörtern (key=clear) ausschließlich nach expliziter Bestätigung eines Sicherheitsdialogs; vollautomatischer Import bei Wiederherstellung; strikter Ausschluss bei Anonymisierung und Git-Schutz für Umzugsordner.\r\n" +
            "• Geprüfte Sicherung & Trockenlauf: Robocopy-Differenzabgleich (/L) und SHA-256-Stichprobenprüfung für ca. 20 Dateien je Bibliothek mit detailliertem Pruefprotokoll.txt und Berichtsausweis; interaktiver Trockenlauf (-Trockenlauf) in Wiederherstellen.cmd und Wiederherstellen.ps1 listet alle Aktionen ohne Änderungen auf.\r\n" +
            "• Gesamtläufe in Bauprozess integriert: Veraltete Parameter bereinigt, neue Integrationsfälle für Wartung, Diagnose und System-Umzug ergänzt; verbindliche Ausführung aller Gesamtläufe in Bauen.cmd vor dem Release mit Laufzeitdokumentation in Stand.txt; Reduzierung der Skips von 99 auf 4."),
        new Eintrag("3.85", "29.10.2026", "Sensor-Manifest-Selbstreparatur, lautloser Smartctl-Lifecycle, RTX 5080 Referenz & UI-Standards",
            "• Manifest-Selbstreparatur für Sensoren & Tools: Automatische Korrektur von leeren Prüfsummen im Manifest Tools.json für LibreHardwareMonitor und PawnIO; lautloser Abgleich gegen fest hinterlegte Release-Hashes verhindert Fehlalarme.\r\n" +
            "• Keine Werkzeug-Warnungen im Kundenbericht: Technische Prüfsummenabweichungen oder fehlende optionale Sensor-Treiber werden im internen Protokoll (Start.log) vermerkt und überfluten den Diagnosebericht nicht mehr mit Warnungen.\r\n" +
            "• Lautloser Smartmontools-Lifecycle: Bevorzugung vorhandener smartctl.exe im Tools-Ordner ohne winget-Aufrufe; Deinstallation ausschließlich am Gesamtlaufende mit striktem NSIS-Silent-Schalter (/S) ohne Dialogfenster.\r\n" +
            "• UI-Standards & Ablauf-Optimierung: Schaltfläche in der Laufansicht in 'Zurück' umbenannt; Grafikstresstest bei Lasttest sowie Aufgaben 'PC durchchecken' und 'Stabilität prüfen' standardmäßig aktiv; parallele lesende Prüfungen als Standard aktiviert.\r\n" +
            "• High-End-Referenz RTX 5080 & Desktop-Median: Modernisierung von Desktop_HighEnd.json auf AMD Ryzen 7 9800X3D und NVIDIA GeForce RTX 5080; RX 6800 als weiteres Profil erhalten; Desktop-Median (Referenz_Desktop.json) neu berechnet und autark eingebettet."),
        new Eintrag("3.84", "28.10.2026", "GitHub-Härtung, granulare Umzugs-Messung, lautloser Sensoren-Lifecycle & Text-Feinschliff",
            "• GitHub-Härtung & Git-Disziplin: Striktes Verbot und globale .gitignore-Absicherung für Binärarchive (*.zip, *.7z, *.tar), ausführbare Dateien (*.exe, *.dll, *.sys) und Treiber; Schutz vor automatischen GitHub-Sperren.\r\n" +
            "• Granulare Umzugs-Bibliotheken: Individuelle Auswahl aller Standardbibliotheken (Desktop, Dokumente, Downloads, Bilder, Musik, Videos) mit Schnellauswahl (Alle / Keine); Downloads standardmäßig abgewählt zum Schutz vor Datenbergen.\r\n" +
            "• Echte Größenmessung beim Schnell-Scan: Beseitigung statischer 2-GB-Pauschalen; exakte Ordnergrößenermittlung für Bibliotheken, Profile und C:\\-Zusatzordner mit dynamischer Größenbeschriftung und Speicherplatzkalkulation.\r\n" +
            "• Lautloser Sensoren-Lifecycle: Zuverlässige Unterdrückung interaktiver Deinstallationsdialoge von PawnIO durch umfassende Silent-Parameter (/VERYSILENT /SUPPRESSMSGBOXES /NORESTART /S -uninstall -silent); Deinstallation ausschließlich am Gesamtlaufende.\r\n" +
            "• Text- & Oberflächen-Feinschliff: Anonymisierungsoption in der Fußleiste präzise als 'Personenbezogene Daten entfernen' beschriftet; Seite Versionen vollständig von Mojibake bereinigt und auf übersichtliche Stichpunkte umgestellt."),
        new Eintrag("3.83", "23.10.2026", "Hotfix 3: System-Umzug Schnell-Scan per Knopfdruck, Karten-Layout im Lasttest-Stil & Zeichensatz-Korrektur",
            "• Manueller Schnell-Scan: Der Vorab-Scan startet nun nicht mehr automatisch beim Öffnen der Seite, sondern gezielt per Schaltfläche ('Schnell-Scan durchführen'); erst nach Klick werden installierte Browser, Mail-Clients, Entwickler-Tools und Zusatzordner analysiert und vorausgewählt.\r\n" +
            "• Kartenlayout im Lasttest-Stil: Vollständige Vereinheitlichung aller drei Umzug-Gruppen (Zielmedium, Sicherungsumfang, Status & Sicherung) auf das bewährte Card(content)-Muster mit abgerundetem Rahmen (CardPanel), konsistenten Rändern und bündigen Kanten ohne abgeschnittene Umrandungen.\r\n" +
            "• Beseitigung von Zeichensatzfehlern: Alle Texte und Beschriftungen der Umzugsseite wurden auf saubere Unicode-Ersatzsequenzen umgestellt, wodurch falsch dargestellte Umlaute und Sonderzeichen dauerhaft ausgeschlossen sind."),
        new Eintrag("3.82", "23.10.2026", "Hotfix 2: System-Umzug Prozessablauf, Vorab-Scan, Live-Log & Kartenlayout",
            "• Prozess- & Performance-Härtung: Behebung einer 15-minütigen Verzögerung durch sofortigen Vorab-Ausstieg des Umzug-Hilfsmodus vor der Diagnose-Initialisierung; Ausschluss von UAC-Erhöhungsversuchen im nicht-privilegierten Kontext; Zeitbegrenzungen für externe Werkzeug-Aufrufe (winget export, reg.exe); Beseitigung von Arbeitsspeicher-Spitzen durch Entfernung rekursiver Dateizählungen beim Laden der Seite.\r\n" +
            "• Kategorisierter Schnell-Scan: Automatische Vorab-Erkennung vorhandener Standardbibliotheken, Desktop-Layout-Eigenschaften, des Winget-Paketmanagers sowie tatsächlich installierter Softwareprofile (Webbrowser, Thunderbird, Entwicklungsumgebungen, Hilfswerkzeuge, Windows Terminal); übersichtliche Darstellung mit Status und automatischer Vorauswahl.\r\n" +
            "• Echtzeit-Protokollfenster (Live-Log): Ergänzung eines durchlaufenden, mitlaufenden Protokollfensters in der Benutzeroberfläche zur vollständigen Transparenz über kopierte Dateien, Einzelschritte und Statusmeldungen während der laufenden Sicherung.\r\n" +
            "• Karten- und Menü-Layout: Exakte Breitenanpassung aller Kartenpanel auf einheitliche Gruppenbreite (grpW); Textumbrüche und Ränder optimiert, sodass Umrandungen auf allen DPI-Stufen bündig abschließen und keine Inhalte mehr über den Kartenrahmen hinausragen."),
        new Eintrag("3.81", "23.10.2026", "Hotfix: System-Umzug Optimierung, Profile & Konfigurationen, Performance & Filterung",
            "• System-Umzug Härtung & Performance: Umstellung der Robocopy-Spiegelung auf paralleles Multithreading (/MT:16) und Live-Streaming der aktuell kopierten Dateien und Unterverzeichnisse an die Benutzeroberfläche; Vorankündigung der Datenvolumina je Bibliothek; strikt lesender Zugriff schützt Quellsysteme garantiert vor Veränderungen.\r\n" +
            "• Profile & Konfigurationen (Configs): Umfassende Sicherung und granulare Auswahl für Browser-Profile (Edge, Chrome, Brave, Firefox, Opera, Vivaldi), E-Mail-Clients (Thunderbird), Entwicklungsumgebungen und Editoren (VS Code, Cursor, Notepad++, Git-Konfiguration, PowerShell-Profile), Remotewerkzeuge (FileZilla, WinSCP, PuTTY-Sessions) sowie Windows Terminal; vollautomatisches Zurückspielen im 1-Klick-Restore.\r\n" +
            "• Erweiterte Blacklist für Stammordner: Ausschluss von Treiber-, Cache- und temporären Ordnern auf Laufwerk C:\\ (unter anderem .cache, AMD, Intel, NVIDIA, inetpub, temp); gefundene Zusatzordner standardmäßig deaktiviert zur Vermeidung ungewollt riesiger Sicherungsläufe; exakte Berücksichtigung der Ordnergrößen in der Speicherplatzberechnung.\r\n" +
            "• Oberflächen-Feinschliff: Behebung verschluckter kaufmännischer Und-Zeichen (&) in Optionsfeldern; kompakte Anordnung und visuelle Transparenz während des Kopiervorgangs."),
        new Eintrag("3.8", "23.10.2026", "Modul „System-Umzug & Neuinstallation“ (Backup & 1-Klick-Restore)",
            "• Modul System-Umzug: Neues Kernmodul zur transparenten Sicherung persönlicher Benutzerdaten, Desktop-Zustand und Software-Inventar vor einer Windows-Neuinstallation auf USB-Wechsellaufwerke oder Netzlaufwerke (NAS).\r\n" +
            "• Autarkes Wiederherstellungspaket: Erzeugung von Wiederherstellen.cmd und dynamischem Wiederherstellen.ps1 direkt im Wurzelverzeichnis der Sicherung. Ermöglicht 1-Klick-Restore auf dem neu installierten Windows-System völlig unabhängig von einer Minibench-Installation und passt Benutzerprofilpfade dynamisch an das neue System an.\r\n" +
            "• Desktop-Zustand & Layout 1:1: Sicherung des aktiven Desktophintergrunds (TranscodedWallpaper als Wallpaper.jpg) inklusive Darstellungsstil in Layout.json sowie vollständiger Export der Icon-Koordinaten via Shell-Bags (IconPositionen.reg) und Icons.json.\r\n" +
            "• Software-Inventarisierung & Winget: Automatischer Paketexport über den Windows-Paket-Manager (winget export nach Programme\\winget-pakete.json) sowie Abgleich der Registry-Installationen mit Generierung des Berichts Nicht-Winget-Programme.txt für manuelle Softwareinstallationen inklusive Google-Suchlinks.\r\n" +
            "• Dateisystem-Schutz & Validierung: Automatische Erkennung beschreibbarer Wechsellaufwerke, Warnung bei FAT32-Formatierung (Dateigrößenbegrenzung auf 4 GB) und vorzeitige Speicherplatzprüfung vor Sicherungsbeginn. Robocopy-Spiegelung mit /XJ, /COPY:DAT und Cache-Ausschlussfiltern."),
        new Eintrag("3.73", "17.10.2026", "Kompakte Modulnamen, LMB.exe, mathematische Modellkorrektur, Dashboard-Fallback & Bereinigung externer Quellen",
            "• Kompakte Modulnamen & LMB.exe: Seitenleiste und Kopfzeilen von „Vergleichsdatenbank“ in „Datenbank“ sowie von „Systemänderungen“ in „Änderungen“ gestrafft; ausführbare Datei in prägnantes LMB.exe umbenannt (inklusive LMB.cmd und Abwärtskompatibilitäts-Starter LeosMinibench.cmd).\r\n" +
            "• Dashboard-Optimierungen: Chronologische Sortierung der Systemauswahl und Vergleichs-Chips standardmäßig absteigend nach Messdatum (neueste Systeme zuerst) mit robuster Erkennung deutscher und ISO-Datumsformate; automatisches Sensor-Fallback auf Benchmark-Telemetrie bei fehlender Lasttest-Zeitreihe verhindert leere Graphen.\r\n" +
            "• Mathematische Modellkorrektur: Gesamtsystem-Effizienzscore auf gewichtetes harmonisches Mittel der gemessenen Benchmark-Effizienzen von CPU und GPU umgestellt, wodurch Systeme mit höherer Einzeleffizienz mathematisch garantiert auch einen höheren Gesamteffizienzindex erzielen (Behebung der Marvin-vs-TORRENT-Anomalie); Nutzungsprofil Workstation durch Anhebung der Mehrkern-Gewichtung (CPU_MT auf 6,0 bzw. 60–65 % Gesamteinfluss) praxisgerecht kalibriert.\r\n" +
            "• Bereinigung externer Quellen: Entfernung privater Repository-Mirrors im Optimierungsmodul; Bezug von Fremdwerkzeugen ausschließlich über offizielle Herstellerseiten, GitHub-Releases oder winget mit fester SHA-256-Prüfsumme.\r\n" +
            "• Dokumentation & GitHub-Präsenz: Sachliche, moderne Überarbeitung der README.md mit vollständiger Funktionsübersicht, aktualisierten Bildschirmfotos und respektvoller Danksagung an das Projekt Windows Optimisation Pack von Marvin700; strukturierte CHANGELOG.md nach Kategorien (Neu, Verbessert, Behoben)."),
        new Eintrag("3.72", "16.10.2026", "Neue dreiteilige Startseite, interaktiver Schnellstart & System-Feinschliff",
            "• Neue dreiteilige Startseite: Moderne Einstiegsseite nach dem Drei-Fragen-Prinzip („Was ist das für ein PC?“, „Was kann ich hier tun?“, „Was ist seit dem letzten Mal passiert?“) als Standardansicht beim Programmstart mit zwei dynamischen Zuständen für Erst- und Folgestarts.\r\n" +
            "• Interaktiver Schnellstart: Direkte Aufgabenwahl hakt die erforderlichen Module an, lädt sinnvolle Standardprofile und wechselt zur ersten Arbeitsseite; Fußleiste mit deaktiviertem Startknopf „Ablauf wählen“ im Leerzustand und automatischer Aktivierung nach Modulauswahl.\r\n" +
            "• Bereinigung veralteter WinSAT-Funktionen: Vollständige Entfernung aller WinSAT-Messungen, Optionen und Diagramme aus Benchmark, Bericht und Oberfläche zugunsten nativer Messungen.\r\n" +
            "• Automatische Standard-Referenz: Hardware-basierte automatische Wahl von Referenz_Notebook.json bzw. Referenz_Desktop.json je nach Gerätetyp (Notebook vs. Desktop).\r\n" +
            "• System-Feinschliff: Sachliche Benennung der Konfigurationsprüfung im Diagnosebericht, asynchrone Hintergrundprüfung für XMP/EXPO, BIOS-Alter und Netzwerkverbindung sowie verbesserte Dialoggestaltung."),
        new Eintrag("3.71", "15.10.2026", "Präzise Stromverbrauchsschätzung, Startzeit-Transparenz, Profilkarten und Dashboard-Korrekturen",
            "• Präzise Stromverbrauchsschätzung: Hardware- und Netzteil-Modellierung mit 230V EU-Effizienzkurven (Unbekannt bis 80 PLUS Titanium) über lineare Stützstellen-Interpolation (5 % bis 100 % Last); interaktive Konfiguration von Nennleistung (Watt) und Effizienzklasse direkt im HTML-Bericht mit Live-Neuberechnung aller Verbrauchswerte, Auslastungsgrade und Stromkosten sowie browserseitiger Persistenz; automatische Erkennung mobiler Plattformen mit OEM-Netzteil-/Akkumodell ohne ATX-Netzteilwahl; genaue DC-Berechnung inkl. VRM-Wandlerverlusten, AMD-Radeon-TBP-Zuschlägen, DIMM-, Datenträger- und Lüfter-Basisverbräuchen sowie Überlastwarnung (> 85 % unter Volllast).\r\n" +
            "• Startzeit-Transparenz & Benchmark-Referenz: Standardmäßig geöffnete Boot-Performance-Sektion mit getrennter Ausweisung von Kernel- und Treiberstart (MainPathBootTime, Desktop einsatzbereit) und Hintergrund-Initialisierung (BootPostBootTime, vollständiger Leerlauf); Nutzungsprofile (Gaming, Büro, Workstation) und Komponentenkarten im Benchmark mit transparentem Hover-Tooltip zur exakten Zusammensetzung und Gewichtung der Teilwerte; Referenzauswahl (Gespeicherte Referenz, Mediane, Datenbankeinträge) und Referenz-Speichern in der Benutzeroberfläche wiederhergestellt.\r\n" +
            "• Dashboard & Dark Mode: Horizontale und vertikale Trennlinien in Spalte 1 im Dark Mode mittels kontrastreicher Randlinien und z-index-Priorisierung repariert; Emojis (🎮, 💼, 🚀, 📊) beibehalten; Dashboard-Öffnen bei Erstbenutzung ohne Parameterfehler stabilisiert."),
        new Eintrag("3.7", "15.10.2026", "Schnell behebbare Systemfehler, Startzeit-Analyse, Sensoren-Harmonisierung und modulares Dashboard",
            "• Schnell behebbare Konfigurationsfehler: Automatische Erkennung von LAN-Verhandlungsrate gebremst (100 Mbit/s oder Halbduplex an Gigabit/2.5GbE-Adaptern), Monitorkabel an iGPU statt dGPU bei Desktops, Hz-Bremse bei Monitoren >= 75 Hz auf 60 Hz limitiert, inaktivem RAM-Speicherprofil (XMP/EXPO/DOCP) und veraltetem BIOS (> 2 Jahre) mit direkten Hersteller-Supportlinks sowie transparenter Bestätigung der Prüfung im Bericht.\r\n" +
            "• Startzeit-Analyse: Aufschlüsselung der Boot Performance aus Event 100 (Kernel-Initialisierung, Desktop/PostBoot) und BIOS-POST-Dauer mit visueller Wasserfall-/Stack-Kaskade im Bericht (eingeklappt am Berichtsende) sowie Erfassung von Autostart-Verzögerern (Event 101-110 ab 1,0 s); robuster Fallback ohne Schätzwerte bei deaktiviertem Protokoll.\r\n" +
            "• Sensoren-Harmonisierung: Vereinheitlichte 4-Stufen-Zustandsmaschine (Vollständig, Eingeschränkt, Inaktiv, Fehler) für Treiber und Monitoring; automatische Treiberinitialisierung bei Vorliegen von Administratorrechten ohne störende Rückfragen und garantierte restlose Treiberbereinigung beim Beenden.\r\n" +
            "• Benchmark-Vereinfachung & Dashboard: Entfernen redundanter Dropdowns und Checkboxen (Messdauer, Referenz, DB-Speicherung); Benchmark speichert immer in der Vergleichsdatenbank. Beseitigung der Scrollbars in der Vergleichsmatrix mit Wiederholung der Systemnamen am Tabellenende, gut sichtbaren Zeilentrennlinien in der Basiskolumne und metrischen Einheiten (°C, %).\r\n" +
            "• Modulares Dashboard: Vollständige Trennung des Dashboard-Quelltexts in dedizierte Template-, Stylesheet- und JavaScript-Dateien (dashboard.html, dashboard.css, daten.js, matrix.js, profile.js, diagramme.js) mit build-zeitiger Einbettung."),
        new Eintrag("3.67", "14.10.2026", "Multi-System-Sensorverlauf, differenzierte Nutzungsprofile und kalibrierte Moduldauern",
            "• Multi-System-Sensorverlauf: Achsenbeschriftung Temperatur (°C) vollständig sichtbar durch vergrößertes linkes Padding (75 px) und linksbündige Ausrichtung; Tooltip mit kompakten Systemnamen (getShortSysName), zweizeiligem Layout und stets vorangestelltem Basissystem (auch ohne Zeitreihe).\r\n" +
            "• Differenzierte Nutzungsprofile: Gewichtung für Gaming (70 % GPU-FPS, 20 % ST, 10 % RAM/SSD; Kerne > 8 neutral), Büro/Desktop (45 % SSD-Reaktionszeit, 35 % ST, 20 % RAM-Latenz; 0 % GPU/MT) und Workstation (45 % MT, 20 % Instruktionen, 20 % RAM-Bandbreite, 15 % Dauertransfer); redundante Stromverbrauchs-Badges im Profilgitter entfernt.\r\n" +
            "• Hervorhebung des Basissystems: Markante Akzent-Umrandung mit Anker-Symbol im Auswahlbereich, durchgehende Hintergrundhervorhebung mit 100-%-Basis-Badge in Hardware- und Matrix-Tabelle sowie Akzent-Rahmen in den Profilkarten.\r\n" +
            "• Hardware-Tabelle aufgeräumt: Redundante Berichtszeile entfernt; kompakte Datenträger-Zusammenfassung nach Typ und Gesamtkapazität mit vollständiger Modellliste im Hinweis beim Überfahren.\r\n" +
            "• Realistische Laufzeitschätzungen: Grundzeit der Diagnose auf 0 Min. gesenkt, Zuschläge für Systemprüfungen und WinSAT auf reale SSD-Dauern kalibriert."),
        new Eintrag("3.66", "14.10.2026", "Dark Mode beim Programmstart, Dashboard-Telemetrie und GPU-Effizienz in FPS/Watt",
            "• Dark Mode beim Start: Bevorzugter Farbmodus (SetPreferredAppMode) wird vor der Control-Initialisierung gesetzt; OnShown und ShowPage wenden die nativen Win32-Themes für Scrollbars auf allen Fenstern und Containern (content, pnlCards, lvDb, txtLog) an.\r\n" +
            "• Sensor-Status-Badge: Die Kopfzeile zeigt ein dezentes Status-Badge für den aktiven Treiber (LHM + PawnIO aktiv oder Windows-Fallback).\r\n" +
            "• Dashboard-Telemetrie: Export-BenchDashboardHtml wird nach der Archivierung ausgeführt; Unterstützung für .minibench-Archive und direktes CSV-Einlesen.\r\n" +
            "• Leistungskurven & Dual-Achsen: Das Multi-System-Dashboard visualisiert Temperatur (°C) auf der linken Achse und Leistung (Watt) auf der rechten Achse; Infokarte mit Peak-Werten bei Läufen ohne Zeitreihe.\r\n" +
            "• GPU-Effizienz in FPS/Watt: Berechnung der GPU-Effizienz strikt auf Basis tatsächlicher Render-FPS (GPU|REND) statt synthetischer Renderpunkte; Beschriftung im HTML-Bericht auf FPS/W korrigiert.\r\n" +
            "• HTML-Bericht Navigation: Fixierte Abschnittsnavigation (sticky) mit dezentem Schatten und flüssiger Nach-oben-Schaltfläche."),
        new Eintrag("3.65", "14.10.2026", "Einheitliche Karten, Wartung im Aufbau der Optimierung, angeglichene Laufansicht und Korrekturen nach dem ersten Windows-Test",
            "• Einheitliche Karten: Optionen der Diagnose, Tabellen des Lasttests, die Paketauswahl der Tools und die Listen der Laufansicht stehen in abgerundeten Karten wie die Werkzeugkarten.\r\n" +
            "• Wartung im Aufbau der Optimierung: Jede Gruppe mit Beschreibung, Alle und Keine, Etiketten rechts und Knopf Alle aufklappen; die Befehle stehen im Hinweis.\r\n" +
            "• Laufansicht angeglichen: Titelgröße, Karte um die Listen, Etiketten in normaler Schreibweise, Bericht öffnen als großer Hauptknopf, Protokollfeld im Hellschema hell.\r\n" +
            "• Korrekturen: Zeitangabe unter dem Diagnoseprofil berücksichtigt die parallele Ausführung, die Fußleiste nennt Diagnose (parallel) an der richtigen Stelle, die Knöpfe der Optimierung stehen in zwei Zeilen, Einzahl bei einem verwalteten Eintrag, gekürzter Text der Netzlaufwerk-Karte, größeres Schildsymbol im Knopf Starten, einzeilige KPI-Kopfzeile im Diagnosebericht ohne Überlauf der Zuverlässigkeits-Kachel."),
        new Eintrag("3.64", "14.10.2026", "Überarbeitete Oberfläche: klare Navigation, eindeutiger Startknopf, Etiketten für Risikostufen und einheitliches Raster",
            "• Seitenleiste in zwei Gruppen (Ablauf mit Haken, Werkzeuge ohne), angezeigte Seite nur über Akzentbalken, geschätzte Dauer je angehaktem Modul.\r\n" +
            "• Kopfzeile flacher mit Symbolknöpfen für Farbschema und Info; die Seite Änderungen heißt Systemänderungen.\r\n" +
            "• Fußleiste mit Modulen in Ablaufreihenfolge und Gesamtdauer, Startknopf mit Beschriftung nach Auswahl (etwa Diagnose starten) und ausreichendem Kontrast im Dunkelschema; Voreinstellungen und Ablage links, die Ablage öffnet den Datenordner.\r\n" +
            "• Zusammenfassung vor dem Start nur bei Eingriffen, Neustarts oder ohne Wiederherstellungspunkt, statt getrennter Rückfragen von Wartung und Optimierung.\r\n" +
            "• Diagnose mit drei Profilen als Segmentschalter (Funktionstest und Nur Absturzanalyse entfallen), Lesende Prüfungen parallel ausführen statt Schneller Modus, Aufklappgruppe Prüfungen.\r\n" +
            "• Benchmark mit Detailzeilen, Laufwerksliste mit freiem Platz, Referenz-Zustand als eigene Zeile. Lasttest als Tabelle mit Gesamtdauer, Akkuhinweis und PawnIO-Etikett.\r\n" +
            "• Wartung und Optimierung mit Etiketten für Ändern, Eingriff, Neustart und Zustand, Legende oben und Warnung ohne Wiederherstellungspunkt. Tools ohne doppelte Bildlaufleiste, Werkzeugkarten mit Zustand und festen Knopfspalten, Netzlaufwerk als eigener Bereich."),
        new Eintrag("3.63", "13.10.2026", "Geschätzter Gesamtsystemverbrauch, Effizienz-Metriken (Punkte pro Watt) und interaktiver Stromkostenrechner",
            "• Geschätzter Gesamtsystemverbrauch: Realistische Modellierung der internen DC-Leistung sowie des AC-Verbrauchs an der Steckdose für Desktop-PCs und Notebooks anhand gemessener CPU-/GPU-Leistungen, Plattformparametern (RAM, Mainboard, Laufwerke, VRM-Verluste) und Netzteil-Wirkungsgraden.\r\n" +
            "• Effizienz-Metriken: Ausweisung von Punkten pro Watt für Mehrkern-CPU (CPU|MT / Watt), Grafikkarte (GPU / Watt) und Gesamtsystem (Gesamt-Score / Watt) in HTML-Bericht und Vergleichs-Dashboard.\r\n" +
            "• Interaktiver Stromkostenrechner: Direkte Kalkulation der jährlichen Betriebskosten im HTML-Bericht mit Schiebereglern für tägliche Nutzungszeiten und einstellbarem Strompreis in Cent je Kilowattstunde.\r\n" +
            "• Dashboard-Telemetrie mit Leistungskurven: Multi-System Dashboard visualisiert den Verlauf der Gesamtsystem-Leistungsaufnahme (in Watt) im Zeitreihendiagramm und ergänzt Verbrauchs- und Effizienzkennzahlen in Systemkarten und Vergleichstabellen.\r\n" +
            "• Robuste Sensoreinstufung: Systeme ohne Watt-Sensoren weisen Kennzahlen sauber als n/v (kein Leistungssensor) aus; Testen.cmd beendet nach Durchläufen ohne Tastendruck."),
        new Eintrag("3.62", "13.10.2026", "Bedarfsorientierter Lauf-Export (.minibench), Kerne und Threads in allen Referenzen, kompakter Lasttest und automatischer GitHub-Push",
            "• Bedarfsorientierter Lauf-Export (.minibench): Die .minibench-Austauschdatei entsteht nicht mehr automatisch bei jedem Durchlauf, sondern nur bei echtem Export-Bedarf. Nach Abschluss des Laufs steht eine neue Schaltfläche 'Lauf exportieren …' direkt in der Ergebnisansicht bereit (sowie weiterhin auf der Seite Vergleichsdatenbank).\r\n" +
            "• Keine Diagnosebericht.txt bei vorhandenem HTML: Wurde der interaktive HTML-Bericht erfolgreich erzeugt, wird auf die redundante reine Textfassung verzichtet; sie dient nur noch als Sicherheitsrückfall bei Fehlern.\r\n" +
            "• Kerne und Threads in allen Referenzen: Alle mitgelieferten Referenzsysteme (Desktop High-End, Desktop Mittelklasse, Mini-PC APU, Notebook Standard, Workstation Mobil) enthalten nun exakte Werte für reale Kerne und logische Threads und wurden in die eingebetteten Referenzen übernommen.\r\n" +
            "• Kompakter Lasttest als Standard: Die Standardauswahl für die Testdauer von CPU, RAM, GPU und Datenträger auf der Lasttestseite wurde von 15 Minuten auf 2 Minuten verkürzt.\r\n" +
            "• Automatischer GitHub-Push: Bauen.cmd committet und pusht bei bestandenen Tests vollautomatisch nach GitHub und aktualisiert die README.md."),
        new Eintrag("3.61", "13.10.2026", "All-in-One-Austauschformat (.minibench), erweiterter Berichts-Import mit Doppelklick-Verknüpfung, Lasttest-Telemetrie in Referenzen und unterbrechungsfreier Start",
            "• Austauschpaket (.minibench): Ein selbsttragendes ZIP-Paket fasst Datenbankeintrag (Datenbank.json), Berichte (HTML, TXT), Anhang.zip und Telemetriedaten zusammen. Wird am Ende jedes Laufs automatisch im Berichtsordner erzeugt; Export einzelner Läufe direkt aus der Vergleichsdatenbank. Die veraltete KI-Kurzfassung wurde vollständig entfernt.\r\n" +
            "• Erweiterter Import mit Berichtskopie: Der Importdialog verarbeitet neben Ordnern auch Pakete (.minibench, .zip) sowie einzelne JSON-Dateien. Der gesamte Berichtsordner wird mitkopiert und das Feld Ordner korrekt verknüpft, sodass ein Doppelklick in der Vergleichsdatenbank sofort den HTML-Bericht öffnet.\r\n" +
            "• Lasttest-Telemetrie in Referenzen: Alle mitgelieferten Referenzsysteme (inklusive neuer Mittelklasse mit GTX 1070) besitzen strukturierte Lasttestdaten (Höchsttemperaturen für CPU und GPU, Leistungsaufnahme, Taktstabilität). HTML-Bericht und Dashboard weisen Lasttest-Deltas und Drosselungsverhalten gegen die Referenzprofile transparent aus; -MedianAktualisieren berechnet Lasttest-Mediane.\r\n" +
            "• Unterbrechungsfreier Start: Abfrage-Popups vor dem Durchlauf (AskDriver, AskSensorTools) entfernt. Sensormessung mit PawnIO-Treiber ist standardmäßig aktiv und lädt fehlende Sensorwerkzeuge bei bestehender Verbindung lautlos nach. Manuelle Steuerung bleibt auf der Seite Sensoren live erhalten."),
        new Eintrag("3.6", "10.10.2026", "Median-Referenz je Geräteklasse, Diagnose und Wartung übersichtlich, Sensor- und Akkudiagnose aus Praxistests",
            "• Median-Referenz je Geräteklasse: Feste Referenzdateien für Notebook und Desktop (Referenz_Notebook.json, Referenz_Desktop.json), auf Knopfdruck oder über -MedianAktualisieren aus bereinigten Datenbankläufen neu berechenbar, verhindern schwankende Vergleichswerte.\r\n" +
            "• Wartung gruppiert: 23 Wartungsmaßnahmen in vier fachliche Gruppen strukturiert mit Aufklappfunktion, Zählern und Beibehaltung der Schnellauswahl.\r\n" +
            "• Diagnose übersichtlich: Prüfungen auf der Diagnoseseite beim Start standardmäßig eingeklappt mit dynamischer Statuszusammenfassung; klappt bei Benutzerdefiniert automatisch auf.\r\n" +
            "• Dunkles Farbschema: UI.ThemeDialog formatiert alle Formulare und Unterdialoge konsistent mit lesbaren Textfarben ohne schwarze Schrift auf dunklem Grund.\r\n" +
            "• Hardware-Spezifikation: Reale Kerne und logische Threads in der Datenbank erfasst; herstellerbereinigte CPU-Anzeigenamen (Get-CpuAnzeigename) in Berichten, Systemvergleich und Dashboard.\r\n" +
            "• Dashboard und Telemetrie: Multi-System-Sensorverlauf mit GPU-Metriken (Takt, Watt, IGpu) vor Befunden platziert, synthetische Lasttestkurven entfernt, Profilkarten nach Punktzahl sortiert.\r\n" +
            "• Sensor- und Praxistest-Härtung: Hintergrundlastprüfung vor Messungen (> 15 % verwirft Leerlauf-Etikett mit 90/80 °C Schwellen), Akku-Historie und Plausibilität geschützt, Hybridgrafik-Zuordnung (Optimus) bereinigt, unplausible Leerlaufspannungen und Sensortemperaturen unter 5 °C gefiltert, Akkubetrieb im Benchmark protokolliert."),
        new Eintrag("3.54", "09.10.2026", "Netzlaufwerk als Spiegel mit Abgleich auf Knopfdruck, Läufe vollständig entfernen und umbenennen",
            "• Datenordner immer auf dem Stick: Leos Minibench startet ohne Zugriff auf das Netzlaufwerk und findet Werkzeuge und Sensoren immer auf dem Stick. Vorher konnte ein nicht erreichbares NAS den Start blockieren, und Tools wurden auf dem NAS gesucht.\r\n" +
            "• Netzlaufwerk als Spiegel: Aktualisieren auf der Seite Vergleichsdatenbank gleicht Berichte, Datenbank, Änderungsprotokolle, Voreinstellungen und Referenz in beide Richtungen ab. Die neuere Fassung gilt, die ältere und alles Gelöschte kommt ins Archiv. Fehlt auf einer Seite ein großer Teil der Daten, hält der Abgleich an und fragt nach. Unterwegs funktioniert alles ohne NAS.\r\n" +
            "• Netzlaufwerk einrichten: Pfad und Benutzer stehen nur noch in Minibench-Daten\\Netzwerk.json auf dem Stick, das Kennwort wird nicht gespeichert, die Verbindung ist nicht dauerhaft. Ein Pfad mit nur einem \\ am Anfang (Ursache des Ordners TRUENAS auf dem Stick) wird abgelehnt.\r\n" +
            "• Vergleichsdatenbank: Entfernen verschiebt Eintrag und Berichtsordner ins Archiv, Name ändern benennt auch Datei und Berichtsordner um.\r\n" +
            "• Datenpflege: PawnIO-Merker und Start.log bleiben stehen, verwaiste temporäre Dateien im Laufzeitordner werden unter Windows PowerShell 5.1 wieder gefunden."),
        new Eintrag("3.53", "09.10.2026", "Testsuite nach Fachgebieten, winget mit Änderungsprotokoll, Grafikauswahl im Lasttest",
            "• Softwarepakete der Seite Tools: winget läuft jetzt im Arbeitsprozess mit Frist je Paket und vollständig gelesener Ausgabe (vorher konnte die Installation unbegrenzt hängen). Jede Installation steht als Eingriff auf der Seite Änderungen und lässt sich dort mit winget uninstall zurücknehmen; schon vorhandene Programme bleiben unberührt. Vor dem Start fragt die Oberfläche nach.\r\n" +
            "• Grafikauswahl im Lasttest: Die Wahl der Grafikeinheit auf der Seite Lasttest sprang auf den Wert des Benchmarks zurück; beide Seiten gleichen sich jetzt in beide Richtungen ab.\r\n" +
            "• Absturzabbilder: Parameter mit Kerneladressen (ab 0x8000000000000000) brachen das Lesen eines Minidumps ab; behoben.\r\n" +
            "• Tests: Die 17 Testdateien je Version sind in Dateien nach Fachgebieten aufgegangen (Oberfläche, Sensoren, Messung, Datenbank, Bericht, Ablauf, Optimierung, Aufbau, Release). Die Oberfläche wird je Testlauf nur noch einmal übersetzt und mit einem Selbsttest geprüft; Testen.cmd -Datei Name startet einzelne Dateien.\r\n" +
            "• Bauen.cmd: Commit-Nachricht aus dieser Versionshistorie statt fester Liste, Commit nur nach bestandenen Tests, ohne BOM am Dateianfang."),
        new Eintrag("3.52", "07.10.2026", "Netzlaufwerk-Härtung, Dashboard-Link-Fix, optimierte Datenpflege, aufgeräumte Optionen und vollständige Historie",
            "• Netzlaufwerk- und NAS-Härtung: Klare Trennung zwischen Berichten/Datenbank auf dem Netzlaufwerk und strikt lokalen Binaries/Caches auf dem USB-Stick oder im lokalen Temp-Verzeichnis. Ausnahme 'Pfadformat nicht unterstützt' und CAS-Sicherheitsblockaden bei OpenRead und externen Treibern (smartctl, PawnIO, LibreHardwareMonitor) behoben.\r\n" +
            "• Dashboard-Link-Korrektur: Relative Pfadauflösung von Berichts-Links im interaktiven Multi-System-Dashboard (Dashboard.html) bereinigt; Auflösung auf <Lauf-Ordner>/Diagnosebericht.html mit Vorwärtsslash ohne doppeltes Berichte-Präfix (ERR_FILE_NOT_FOUND behoben).\r\n" +
            "• Erweiterte Datenpflege: Verwaiste und beschädigte Datenbankeinträge (ohne Berichtsordner oder leere JSON-Dateien) werden automatisch ins Archiv verschoben; verwaiste Locks, Checkpoints und temporäre Reste im Laufzeitordner werden bereinigt und freigegebener Speicherplatz detailliert protokolliert.\r\n" +
            "• Oberflächen-Verfeinerung: Redundante Vergleichs-Checkliste auf der Benchmark-Startseite entfernt; Diagnose-Optionen in moderne Fluent-Karten mit Icons kategorisiert; Startfenstergröße weiter vergrößert für scrollbalkenfreie Darstellung.\r\n" +
            "• Vollständige Versionshistorie: Dokumentation aller Einzelversionen von 1.0 bis 1.8 mit konkreten Changelogs nachgepflegt."),
        new Eintrag("3.51", "07.10.2026", "Dashboard-Berichtsverlinkung, Referenz-Deduplizierung & persistente Netzlaufwerke",
            "• Dashboard-Berichtsverlinkung: Vollständige Diagnoseberichte können im Multi-System-Dashboard (Dashboard.html) direkt durch Klick auf Systemnamen oder über die neuen Bericht-Schaltflächen geöffnet werden. Auf der Vergleichsseite in der Benutzeroberfläche steht zusätzlich ein Button 'Bericht öffnen' bereit.\r\n" +
            "• Bereinigung der Referenzprofile: Referenzsysteme erscheinen im Dashboard sauber und ausschließlich einmalig unter 'Referenzprofile (Eingebettet)' mit Stern-Symbol (★) statt fälschlich zusätzlich in der regulären Datenbankliste.\r\n" +
            "• Persistente Netzlaufwerk-Verbindung: Die Konfiguration für NAS- und Netzlaufwerkablagen (Netzwerk.json) wird redundant an allen lokalen Speicherorten abgelegt. Beim Programmstart wird die Verbindung bei Bedarf automatisch via net use wiederhergestellt, sodass alle Berichte und Benchmark-Daten der Freigabe sofort geladen werden."),
        new Eintrag("3.5", "06.10.2026", "Taskleisten-Task-Beenden, Minimal-Preset-Standard, winget-Softwarepakete, NAS-Netzlaufwerke & interaktive Berichtsdiagramme",
            "• Fehlerbehebung & Optimierungs-Presets: Entkopplung der Taskleisten-Gruppierung vom Task-Beenden; TaskbarEndTask als eigenständiger Eintrag mit Vorlagen MSE. Das Preset Minimal wurde auf ein schlankes Basispaket gestrafft und ist die neue Standardvorauswahl beim Start.\r\n" +
            "• Erweitertes Fensterlayout: Vergrößerte, responsive Startfenstergröße (1220x740 mit Begrenzung auf 95 % / 92 % des Arbeitsbereichs) für optimalen Überblick ohne Überlauf auf skalierten Displays.\r\n" +
            "• Softwarepakete installieren (winget): Neues Werkzeug im Modul Tools zur einfachen Installation populärer Standardprogramme (Chrome, Firefox, Opera, Steam, Discord, Notepad++, OnlyOffice, 7-Zip, VLC) per Mausklick mit Statuserkennung.\r\n" +
            "• NAS- & Netzlaufwerk-Integration: Konfigurierbare Netzwerkpfade für Berichte und Vergleichsdatenbank (Netzwerk.json) mit schnellem Verbindungsdialog und robustem, automatischem lokalem Fallback bei Verbindungsverlust.\r\n" +
            "• Berichts-Diagramme & Bereinigung: Sensor-Charts im Diagnosebericht mit interaktiven Hover-Tooltips (Zeitstempel, °C, GHz, Watt und Auslastung) sowie Bereinigung der Befunde-Suchleiste zugunsten übersichtlicher Stufen-Filter."),
        new Eintrag("3.4", "06.10.2026", "Modul Tools (Portable Werkzeuge & System-Shortcuts), Leos Empfehlung & interaktiver Hauptbericht",
            "• Neues Modul Tools: Eigene Navigationsseite mit portablen Werkzeugen (Revo Uninstaller, MiniTool Partition Wizard, WizTree) inklusive automatischer Erkennung und Administrator-Start sowie System-Shortcuts (Ins BIOS/UEFI neu starten, Datenträgerverwaltung, Geräte-Manager, Zuverlässigkeitsverlauf).\r\n" +
            "• Erweiterung 'Leos Empfehlung': Neue Optimierung für Windows 11 zum sofortigen Beenden von Tasks per Rechtsklick auf die Taskleiste (TaskbarEndTask) sowie Desktop-Kontextmenü-Shortcut für UEFI-Neustarts.\r\n" +
            "• Interaktiver Diagnosebericht & Designangleichung: Hauptbericht (Diagnosebericht.html) mit dynamischer Abschnitt-Navigation, Live-Suche und Stufen-Filtern für Befunde, schwebenden Tooltips auf Sensor-Messpunkten und einheitlicher kontraststarker Farbwelt auf Basis von Stil.ps1."),
        new Eintrag("3.32", "06.10.2026", "Dark-Mode-Feinschliff (Scrollbars, ComboBox, Header & Kontraste) und Konsolidierung des Systemvergleichs",
            "• Dark-Mode-Feinschliff: Native dunkle Win32-Scrollbars für Inhalts- und Navigationsbereiche über SetPreferredAppMode (ForceDark) und SetWindowTheme (DarkMode_Explorer), neue DarkComboBox für nahtlos dunkle Dropdown-Menüs, einheitlich abgedunkelte Tabellenköpfe (Owner-Draw SysHeader32) und kontrastreiche Textdarstellung für deaktivierte Steuerelemente ohne Windows-GDI-Schattendruck.\r\n" +
            "• Konsolidierung des Systemvergleichs: Das interaktive Multi-System-Dashboard deckt sämtliche Hardware-Gegenüberstellungen, Benchmark-Matrizen und Befundvergleiche ab; die redundante statische Vergleichsfunktion wurde zugunsten eines einheitlichen Workflows abgelöst und die Vergleichsdatenbank aktualisiert."),
        new Eintrag("3.31", "06.10.2026", "Multi-System-Vergleich im Dashboard (N >= 2), nativer WinForms Dark Mode & Build-Synchronisation",
            "• Multi-System-Vergleich im Dashboard: Beliebige Anzahl von Systemen (N >= 2) mit dynamischer Auswahl, direkter Hardware-Gegenüberstellung, vollständiger Benchmark-Matrix aller Metriken (inkl. Bestwert-Hervorhebung), synoptischem Befundvergleich und mehrfarbigem Canvas-Chartvergleich für Takt und Temperatur.\r\n" +
            "• Paralleler Betriebsmodus in der Oberfläche: Klassischer statischer Vergleichsbericht und interaktives Multi-System-Dashboard stehen in Toolbar und Kontextmenü gleichberechtigt zur Verfügung.\r\n" +
            "• Nativer GUI Dark Mode: Vollständig integriertes dynamisches Theme-System (Hell/Dunkel) für die WinForms-Oberfläche mit schnellem Umschalter in der Titelleiste, DWM Immersive Dark Mode für die Titelleiste und dauerhafter Speicherung in Einstellungen.json (Fallback: Windows-Systemdesign).\r\n" +
            "• Build- und Git-Synchronisation: Bauen.cmd synchronisiert und committet Quelltexte und Dokumentation nach erfolgreichem Bau und bestandenen Tests automatisch lokal in Git."),
        new Eintrag("3.3", "06.10.2026", "Interaktives Benchmark- & Diagnose-Dashboard, Lasttest-Telemetrie-Visualisierung, Fluent 2-Design und Dark Mode",
            "• Eigenständiges HTML5-Dashboard: Vollständig offline-fähiges, interaktives Analyse- und Vergleichs-Dashboard mit Export-Funktion (Export-BenchDashboardData, New-BenchDashboardHtml) und Direktaufruf aus der Vergleichsseite sowie per CLI (-Dashboard).\r\n" +
            "• Dual-Axis Telemetrie-Visualisierung: Interaktiver HTML5-Canvas-Chart für Takt (GHz/MHz) und Temperatur (°C) über den Lasttestverlauf mit TjMax-Referenzlinie, dynamischen Drosselungs-Markierungen (Thermal/Power Throttling) und Cursor-Tooltips.\r\n" +
            "• Fluent 2 / Wintoys-UI & Theming: Kachel- und Kartendesign im Windows 11 Fluent 2-Look, interaktiver Dark/Light-Mode Switch mit Zustandsspeicherung in localStorage.\r\n" +
            "• Umfassende Vergleichsmetriken: Live-Gegenüberstellung gegen alle fünf eingebetteten Referenzprofile mit Gaming-, Büro- und Workstation-Scores sowie Differenz-Pillen für CPU, RAM, GPU und Datenträger."),
        new Eintrag("3.2", "06.10.2026", "Fluent 2 / Wintoys-Look, Windows 11 DWM-Rundungen, Segoe-Icons und responsive Notebook-Skalierung",
            "• Fluent 2-Designsystem: Modernes helles Farbschema (#F9F9FB Hintergrund, weiße Karten mit feinem 1px-Rahmen #E5E7EB, Windows 11-Akzentblau #0067C0 und pastellfarbene Status-Badges).\r\n" +
            "• Moderne Steuerelemente: Eigener ToggleSwitch im Windows 11-Pillendesign mit animiertem Schieber und barrierefreiem Fokus; FluentCard-Komponente für modulare Optionen mit Segoe-Icons und integrierten Schaltern.\r\n" +
            "• Modul-Navigation: Neugestaltetes NavItem im Windows 11-Sidebar-Stil mit 6 px Eckenrundung, aktivem 3 px-Akzentbalken und gestochen scharfen Segoe-Symbolen (Segoe Fluent Icons / MDL2 Assets).\r\n" +
            "• DWM-Integration: Echte Windows 11-Fensterabrundung über DWMWA_WINDOW_CORNER_PREFERENCE (DWMWCP_ROUND), PerMonitorV2 DPI-Awareness ohne veraltetes SetProcessDPIAware.\r\n" +
            "• Zentraler DPI-Helper & Notebook-Sicherheit: Vollständige Skalierung über UI.S(...) und UI.SF(...), dynamische Fenstergröße anhand des Arbeitsbereichs (WorkingArea) gegen Überlauf auf 1080p-Notebooks mit 150 % Skalierung."),
        new Eintrag("3.1", "05.10.2026", "Bugfix-Release: Vergleichsseite, eingebettete Referenzdaten, CPU-Benchmark und Grafiktest auf Einsteiger-GPUs",
            "• Vergleichsseite: Fehlerbehebung beim Einlesen der Systemdatenbank und Logging im JSON-Parser (DbEntry.Load), sodass Systeme zuverlässig angezeigt werden.\r\n" +
            "• Eingebettete Referenzdaten: Fünf anonyme Referenzprofile (Desktop High-End bis Notebook Standard) direkt im Skript eingebettet und bei leerer Datenbank automatisch entpackt.\r\n" +
            "• Prozessor-Benchmark: Behebung der CPU-Leistungsregression durch verbindliche Ausführung unter Windows PowerShell 5.1 ohne JIT- und Sensor-Overhead.\r\n" +
            "• Grafik-Benchmark: Robuste Bildzeit- und Perzentil-Erfassung bei niedrigen Bildraten (Intel UHD Graphics auf Notebooks), Ausfallschutz für Hybrid-Grafik und zusätzliche Feature-Level."),
        new Eintrag("3.0", "05.10.2026", "Dual-Runtime (PowerShell 7 / 5.1), sicheres Schritt-Überspringen, Frametime-Latenzen (0,1 % Low & Mikroruckler), eingebettete Referenzen und Tabellenoptik",
            "• Dual-Runtime-Unterstützung: Automatische Bevorzugung von PowerShell 7 (pwsh.exe) für maximale Geschwindigkeit mit nahtlosem Fallback auf Windows PowerShell 5.1.\r\n" +
            "• Sicheres Überspringen langwieriger Einzelschritte mit dynamischer Freigabe (SKIP_ALLOWED) und sauberem Abbruch von Hintergrundjobs ohne Skriptfehler.\r\n" +
            "• Erweiterte Frametime-Analyse im Rendertest: Erfassung von 0,1 %-Low FPS und Mikroruckler-Anteil (Frames über 50 ms) in Messwerten, Kurven und Berichten.\r\n" +
            "• Fünf eingebettete Referenzprofile (Desktop High-End bis Notebook Standard) direkt im Build für sofortige Vergleiche ohne externe Dateien, Standard-Referenz Desktop Mittelklasse.\r\n" +
            "• Bereinigte Benchmark-Darstellung im HTML-Bericht mit bewährter Detailtabellen-Optik unter Beibehaltung des Gesamtleistungs-Banners und der Profilkarten."),
        new Eintrag("2.95", "05.10.2026", "Anonyme Vergleichsdaten, Gesamtleistungs-Banner, UserBenchmark-Profile, Minidump Crash Inspector, Schritt überspringen",
            "• Feste Einbindung von fünf anonymisierten, bereinigten Referenzsystemen von Desktop High-End bis Notebook Standard für sofortige Vergleichbarkeit ab dem ersten Start.\r\n" +
            "• Gesamtleistungs-Banner im Bericht-Header mit prozentualer Gesamtbewertung zur Referenz.\r\n" +
            "• Benchmark-Darstellung im UserBenchmark-Stil: Drei gewichtete Nutzungsprofile (Gaming, Büro/Desktop, Workstation), prominente Komponenten-Köpfe und modernes Spalten-Layout für Messgrößen.\r\n" +
            "• Modul Wartung mit angepasster Standardauswahl für risikoarme Bereinigungen und Schnellwahlschaltern über der Aufgabenliste.\r\n" +
            "• Neue Schaltfläche Diesen Schritt überspringen in der Laufansicht mit Ereignis @@SCHRITT_UEBERSPRINGEN.\r\n" +
            "• Minidump Crash Inspector mit nativer Binäranalyse von Windows-Absturzabbildern (.dmp), Bugcheck-Erkennung und Handlungsempfehlungen.\r\n" +
            "• Grafiktreiber-Gesundheitscheck auf Microsoft Basic Display Adapter, veraltete Treiber (ab 18 Monate) und Treiberabstürze (Event 4101).\r\n" +
            "• Durchlaufzeit-Optimierung durch Zwischenspeicherung statischer WMI- und CIM-Systemabfragen."),
        new Eintrag("2.9", "05.10.2026", "Phasen 0 und 1: ARM64, High-DPI, Modularisierung, Wartung, Gesamtbild und Vergleichsseite",
            "• Hardware-Erkennung mit ARM64-Erkennung und Warnhinweis für ARM64-Systeme im Bericht.\r\n" +
            "• High-DPI-Optimierung mit Per-Monitor V2 DPI-Awareness im Anwendungsmanifest für gestochen scharfe Anzeige bei 150 % bis 225 % Skalierung.\r\n" +
            "• Modularisierung der C#-Oberfläche in übersichtliche Teilklassen (Steuerelemente, Modelle, Vergleich, Seiten).\r\n" +
            "• Modul Reparatur in Wartung umbenannt mit 22 Wartungsschritten, Bereinigung aus Optimierung überführt und Redundanzen im Katalog bereinigt.\r\n" +
            "• Neues Voreinstellungs-Preset Leos Empfehlung als Standard aktiv.\r\n" +
            "• Neugewichtung im Gesamtbild: Prozessor und Grafik erhalten doppeltes Gewicht, der GPU-Rendertest (FPS) dreifaches Gewicht gegenüber Durchsatzwerten.\r\n" +
            "• Vergleichsseite: System-Anzeigename editierbar und Vergleichsdatenbank nach Spalten sortierbar."),
        new Eintrag("2.8", "03.10.2026", "Modul Optimierung, Sensoren ohne LibreHardwareMonitor",
            "• Neues Modul Optimierung: alle Einstellungen des Windows Optimisation Pack, seiner Sophia-Konfiguration und der O&O-Auswahl als 163 einzelne Einträge in 14 Kategorien, mit Vorlagen Minimal, Standard und Erweitert, Zustandsprüfung, Wiederherstellungspunkt und Rückgängig je Einstellung. Sophia Script und O&O ShutUp10++ laufen nicht mehr; DDU und NVIDIA Profile Inspector sind optionale Werkzeuge mit Prüfsumme.\r\n" +
            "• Ohne LibreHardwareMonitor liefern Grafiktreiber und Windows GPU-Temperatur, Takt, Lüfter, Auslastung und, wo vorhanden, die CPU-Leistung; Bericht und Oberfläche nennen den wahren Grund fehlender Werte und bieten das Holen an.\r\n" +
            "• Kurven ohne überlappende Beschriftungen, Unterbrechungen im Benchmark ohne WinSAT, kürzere WLAN- und Zuverlässigkeitstexte, Laufzeit mit Minuten, NVMe-Klasse ohne lesbare Anbindung geschätzt."),
        new Eintrag("2.7", "03.10.2026", "Bedienung, Sensoren im Benchmark, Datenpflege",
            "• Jedes Bedienelement erklärt sich beim Überfahren mit der Maus. Der Benchmark zeichnet während aller Messungen Temperatur, Takt und Leistung auf; der Bericht zeigt sie je Abschnitt (Prozessor, Arbeitsspeicher, Grafik, Datenträger, WinSAT) mit Kurven wie nach dem Lasttest, die Laufansicht zeigt die Kurven live.\r\n" +
            "• Der CPU-Stabilitätstest der Diagnose entfällt, das Modul Lasttest prüft die CPU gründlicher. Neue Seite Versionen mit dieser Historie.\r\n" +
            "• Die Datenpflege verschiebt Lasttests vor v2.67, abgebrochene Läufe ohne Bericht und kurze Läufe ins Archiv, beim Start von selbst und über Aufräumen auf der Seite Vergleichsdatenbank. Bauen.cmd legt den vorigen Build unter Archiv\\v<Version> ab."),
        new Eintrag("2.67", "03.10.2026", "Gleichmäßige CPU-Last im eigenen Prozess",
            "• CPU- und RAM-Last laufen in einem eigenen PowerShell-Prozess ohne Speicherbereinigung; die Lastschleifen kommen ohne Aufrufe aus (Sinus als Polynom). Ursache der ungleichmäßigen Last war Math.Sin in der Rechenschleife: Die Speicherbereinigung konnte die Threads nicht anhalten.\r\n" +
            "• Lasttestergebnisse älterer Versionen (Rechendurchläufe, Unterbrechungen) sind damit nicht vergleichbar; das Rechenwerk des Benchmarks blieb gleich."),
        new Eintrag("2.66", "03.10.2026", "Unterbrechungen messen, Sensoren robuster",
            "• Messung von Unterbrechungen über 50 ms mit den Speicherbereinigungen je Generation in Lasttest, CPU-Test und Benchmark.\r\n" +
            "• Sensoren überstehen verspätete Abfragen (letzte Werte bis 10 s, Ausfall erst nach 30 s), Datenträger werden in einem eigenen Thread gelesen.\r\n" +
            "• KI-Auftrag mit Klickpfad und fertigen PowerShell-Befehlen. Keine Rückfrage mehr vor dem Grafik-Lasttest."),
        new Eintrag("2.65", "02.10.2026", "Praxistest auf ULB-PC und TORRENT",
            "• GPU-Sensorwerte wieder vollständig, RAM-Test neben der CPU-Last mit niedriger Priorität, flüssige Vorschau des Rendertests, Warnung bei einer Bildratengrenze, Auswahl der Grafikeinheit, Lasttest ab 2 Minuten.\r\n" +
            "• Datenträger- und Grafiklast abgesichert, Referenz nur noch über den Haken, Zuverlässigkeit vorn im Bericht, Voreinstellungen zum Weitergeben, kürzere Texte."),
        new Eintrag("2.6", "02.10.2026", "Rendertest, schneller Modus, schneller Start",
            "• Fasst die geplanten Versionen 2.5 und 2.6 zusammen (eine 2.5 gibt es nicht). Lasttest läuft eigenständig und liefert immer ein Ergebnis.\r\n" +
            "• Eigener Rendertest mit Direct3D 11 auf jeder Grafikeinheit. Schneller Modus mit parallelen Prüfungen.\r\n" +
            "• Startfenster sofort, Skript und Arbeitsordner im lokalen TEMP, deutlich weniger Schreibzugriffe auf den Stick (Anhang.zip). Programmsymbol blaues L."),
        new Eintrag("2.4", "02.10.2026", "Praxistest vom 01.10.2026",
            "• Kein leerer Bericht bei einzelnen Modulen, CPU-Takt wie im Task-Manager (PDH), Grenzwerte und unplausible Sensorwerte erkannt, Grafikkarte und Prozessorgrafik getrennt, WinSAT bei Hybridgrafik auf der Grafikkarte.\r\n" +
            "• KI-Datei mit Gewichtungsregeln, Akkubericht, Standby-Sperre während des Laufs, SMART-Langtest höchstens 120 Minuten, Hilfswerkzeuge je Gerät behalten."),
        new Eintrag("2.3", "01.10.2026", "Sensoren",
            "• LibreHardwareMonitor portabel mit festen Prüfsummen, Treiber PawnIO nur nach Rückfrage und nur vorübergehend, Ersatzquellen (Windows, ACPI, nvidia-smi).\r\n" +
            "• Seite Sensoren live, Lasttest mit Kurven, Drosselnachweis und Abbruchschwelle, Sensoren als Momentaufnahme in der Diagnose."),
        new Eintrag("2.2", "01.10.2026", "Neues Fundament",
            "• Quelltext in Teilen (src) mit Bauen.cmd, Modulvertrag je Modul, Risikostufen (Lesen, Ändern, Eingriff, Zerstörend), Änderungsprotokoll mit Rückgängig.\r\n" +
            "• Werkzeug-Manifest mit SHA-256, Datenbankformat 2 mit Geräteidentität, Pester-Tests und Testmatrix. Bedienung, Berichte und Ablage blieben wie in 2.1."),
        new Eintrag("2.0 bis 2.1", "bis 01.10.2026", "Leos Minibench",
            "• Neuer Name Leos Minibench, Start als LeosMinibench.exe vom Stick, Datenordner Minibench-Daten neben der exe (ein Ordner PC-Diagnose-Daten wird übernommen).\r\n" +
            "• Oberfläche mit den Modulen Diagnose, Benchmark, Lasttest und Reparatur, Vergleichsdatenbank (Format 1), HTML- und Textbericht, KI-Datei. smartctl lag im Tools-Ordner noch ohne Manifest. Stand 2.1 ist die Grundlage, die 2.2 in Teile zerlegt hat."),
        new Eintrag("1.8", "30.09.2026", "Gruppierter Benchmark und Referenz",
            "• Der Benchmark ist in vier ausklappbare Blöcke gegliedert, im Bericht und in der Oberfläche. Laufwerke stehen kompakt in einer Zeile pro Laufwerk.\r\n" +
            "• Neue Messungen für CPU (AES-256, SHA-256, Kompression), RAM (Kopieren), GPU (PCIe-Anbindung, Grafikspeicher) und Laufwerke (4K schreiben)."),
        new Eintrag("1.7", "29.09.2026", "Benchmark-Korrektur und schlankere Ausgabe",
            "• Fehler behoben, durch den nur die CPU gemessen wurde. Jeder Teil des Benchmarks läuft jetzt abgesichert für sich.\r\n" +
            "• Die Ausgabe ist entschlackt: Im Ordner liegen nur noch der HTML- und der Textbericht, alles andere steckt in Anhang.zip."),
        new Eintrag("1.6", "28.09.2026", "Benchmark und Lasttest",
            "• Benchmark für CPU (Einzel- und Mehrkern, Takt), RAM (Lesen, Schreiben, Latenz), GPU (WinSAT) und Laufwerke (sequentiell und 4K, ohne Windows-Cache).\r\n" +
            "• Jeder Wert bekommt einen Index für seine Hardwareklasse und wird mit früheren Läufen verglichen. PCIe-Anbindung von Grafikkarte und NVMe wird geprüft.\r\n" +
            "• Lasttest mit wählbarer Dauer, Takt- und Temperaturkurve, Drosselungserkennung und Abbruchknopf."),
        new Eintrag("1.5", "27.09.2026", "Kurztest und neues Design",
            "• Kurztest-Modus, der alles Langwierige überspringt.\r\n" +
            "• Die Oberfläche ist komplett überarbeitet, mit Kacheln, Statuskarten und Reitern, und öffnet sich im Vordergrund.\r\n" +
            "• Die exe fordert Administratorrechte selbst an. Dazu Korrekturen aus dem Code-Review."),
        new Eintrag("1.4", "26.09.2026", "Oberfläche und HTML-Bericht",
            "• Optionale grafische Oberfläche mit Live-Befunden, Testergebnissen und Protokoll.\r\n" +
            "• Grafischer Endbericht als HTML mit Hell- und Dunkelmodus.\r\n" +
            "• Ein Build-Skript kompiliert die exe direkt auf dem Desktop, ganz ohne Download."),
        new Eintrag("1.3", "25.09.2026", "Absturzsicherheit und Korrekturen",
            "• Checkpoints werden direkt auf die Platte geschrieben, damit sie auch einen Absturz überstehen.\r\n" +
            "• Nach einem abgebrochenen Lauf startet eine Absturzanalyse: Bluescreen-Stoppcode, Kernel-Power 41, WHEA-Fehler und der Schritt, in dem der PC ausfiel. Neue Option Absturzanalyse (-AnalyzeLastRun).\r\n" +
            "• Behoben wurden die Fehler aus dem ersten Praxislauf: Auswertung von SFC, Fehlalarme bei NTFS und Store-Apps, SMART-Meldung, Firmwaretyp und Konsolenkodierung."),
        new Eintrag("1.2", "24.09.2026", "Kodierung",
            "• Das Skript repariert sich selbst, wenn die UTF-8-Kennung (BOM) beim Kopieren verloren geht.\r\n" +
            "• Hashtable-Schlüssel mit Umlauten stehen jetzt in Anführungszeichen."),
        new Eintrag("1.1", "23.09.2026", "Starten und Fortschritt",
            "• Start-CMD mit Menü und eine exe als Starter.\r\n" +
            "• Die Administratorrechte holt sich die CMD selbst, und das Fenster bleibt bei Fehlern offen. Klare Fortschrittsbalken für den Gesamtlauf und den einzelnen Schritt."),
        new Eintrag("1.0", "22.09.2026", "Grundversion",
            "• Diagnoseskript für Windows 11. Es erfasst die Hardware und das System: Firmware, TPM, BitLocker, CPU, RAM-Module, GPU, Datenträger, SMART, Akku, Netzwerk, Treiber, Updates, Sicherheit, Autostart und Software.\r\n" +
            "• Dazu kommen Tests: WinSAT, chkdsk-Onlinescan, DISM und SFC, Defender-Schnellscan, SMART-Langtest, RAM-Mustertest, CPU-Stabilitätstest, Netzwerk- und Energieanalyse sowie die Auswertung der Ereignisprotokolle.\r\n" +
            "• Der komplette Bericht landet in der Zwischenablage und als Textdatei auf dem Desktop.")
    };
}
